INSERT INTO system_vocabulary_words (id, set_id, topic_id, part_id, word, ipa, cefr, part_of_speech, meaning_vi, definition_en, example_en, example_vi, example_toeic, audio_us, audio_uk, image_url, synonyms, antonyms, phrases, confusables, word_family, audio_voices, note_vi, toeic_topic, difficulty_level, order_index) VALUES
('19592f46-cebb-533e-9db3-36e53f1ea377', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '09f1d27d-1950-545a-86bf-26ddd038fd16', 'a6fee9f7-e500-567e-8765-7a053179be07', 'conquer', '/ˈkɒŋkə(r)/', 'B2', 'verb', 'Chiếm đoạt, đánh bại; vượt qua khó khăn.', 'to take control of a country or to defeat a difficult situation.', 'The ambitious entrepreneur managed to conquer new international markets within two years.', 'Nhà doanh nghiệp nhiều hoài vọng đã thành công chinh phục các thị trường quốc tế mới trong vòng hai năm.', '{\"en\": \"Our marketing team hopes to conquer the European market with this new product line.\", \"vi\": \"Đội ngũ tiếp thị của chúng tôi hy vọng sẽ chinh phục thị trường châu Âu với dòng sản phẩm mới này.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/conquer-ljspeech-d9fe2033.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/conquer-cori-d9fe2033.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/conquer-421f0320.webp', '[\"defeat\", \"overcome\", \"vanquish\"]', '[\"lose\", \"surrender\", \"fail\"]', '[{\"phrase\": \"conquer a market\", \"meaning\": \"chinh phục thị trường\"}, {\"phrase\": \"conquer a fear\", \"meaning\": \"vượt qua nỗi sợ hãi\"}]', '[{\"word\": \"concur\", \"note_vi\": \"concur có nghĩa là đồng ý, đồng tình.\"}]', '[{\"pos\": \"noun\", \"word\": \"conqueror\"}, {\"pos\": \"noun\", \"word\": \"conquest\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/conquer-cori-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-aru0-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-aru5-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-aru6-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-aru10-d9fe2033.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/conquer-aru9-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-aru3-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-aru7-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-aru8-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-aru2-d9fe2033.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/conquer-ljspeech-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-lt408-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-lt138-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-lt624-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-lt396-d9fe2033.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/conquer-lt498-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-lt132-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-lt288-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-lt42-d9fe2033.mp3\", \"/storage/v1/object/public/pronunciation/v2/conquer-lt90-d9fe2033.mp3\"]}}', 'Trong TOEIC, từ này hay dùng với nghĩa bóng là vượt qua thử thách hoặc chiếm lĩnh thị trường.', 'marketing', 1, 0),
('591ed57f-6c5f-5e1f-ab15-97c0bbaf6ca1', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '09f1d27d-1950-545a-86bf-26ddd038fd16', 'a6fee9f7-e500-567e-8765-7a053179be07', 'peace', '/piːs/', 'B1', 'noun', 'Tình trạng không có chiến tranh hoặc xung đột.', 'a situation where there is no fighting or disagreement between people or countries.', 'After years of conflict, the two nations finally signed a peace treaty.', 'Sau nhiều năm xung đột, hai quốc gia cuối cùng đã ký hiệp ước hòa bình.', '{\"en\": \"The management team worked hard to restore peace within the office after the dispute.\", \"vi\": \"Đội ngũ quản lý đã làm việc chăm chỉ để khôi phục sự hòa bình trong văn phòng sau cuộc tranh chấp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/peace-ljspeech-d7c50a08.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/peace-cori-d7c50a08.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/peace-7abd40a4.webp', '[\"harmony\", \"tranquility\"]', '[\"war\", \"conflict\"]', '[{\"phrase\": \"peace treaty\", \"meaning\": \"hiệp ước hòa bình\"}, {\"phrase\": \"keep the peace\", \"meaning\": \"giữ gìn trật tự\"}]', '[{\"word\": \"piece\", \"note_vi\": \"Piece là một mảnh, một phần; phát âm giống nhưng nghĩa khác hoàn toàn.\"}]', '[{\"pos\": \"adjective\", \"word\": \"peaceful\"}, {\"pos\": \"adverb\", \"word\": \"peacefully\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/peace-cori-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-aru0-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-aru5-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-aru6-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-aru10-d7c50a08.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/peace-aru9-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-aru3-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-aru7-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-aru8-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-aru2-d7c50a08.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/peace-ljspeech-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-lt408-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-lt138-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-lt624-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-lt396-d7c50a08.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/peace-lt498-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-lt132-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-lt288-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-lt42-d7c50a08.mp3\", \"/storage/v1/object/public/pronunciation/v2/peace-lt90-d7c50a08.mp3\"]}}', 'Đừng nhầm lẫn với \'piece\' (mảnh, miếng) vì hai từ này đồng âm.', 'office', 1, 1),
('3c994a67-dd0e-5fb8-a34a-9b234ee9b92c', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '09f1d27d-1950-545a-86bf-26ddd038fd16', 'a6fee9f7-e500-567e-8765-7a053179be07', 'figure out', '/ˈfɪɡə aʊt/', 'B1', 'verb', 'Tìm ra cách giải quyết hoặc hiểu rõ điều gì đó.', 'to understand or solve something after thinking carefully about it.', 'Engineers are attempting to figure out the exact cause of the system failure.', 'Các kỹ sư đang cố gắng tìm ra nguyên nhân chính xác của sự cố hệ thống.', '{\"en\": \"The IT team is trying to figure out why the server crashed yesterday.\", \"vi\": \"Đội ngũ CNTT đang cố gắng tìm hiểu lý do tại sao máy chủ bị sập ngày hôm qua.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/figure-out-ljspeech-7c63de27.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/figure-out-cori-7c63de27.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/figure-out-6b044a8b.webp', '[\"solve\", \"work out\", \"understand\"]', NULL, '[{\"phrase\": \"figure out a way\", \"meaning\": \"tìm ra một cách\"}, {\"phrase\": \"figure out the problem\", \"meaning\": \"tìm ra vấn đề\"}]', '[{\"word\": \"find out\", \"note_vi\": \"Find out là phát hiện thông tin; figure out là tư duy để hiểu/giải quyết.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/figure-out-cori-7c63de27.mp3\", \"/storage/v1/object/public/pronunciation/v2/figure-out-aru0-7c63de27.mp3\", \"/storage/v1/object/public/pronunciation/v2/figure-out-aru5-7c63de27.mp3\", \"/storage/v1/object/public/pronunciation/v2/figure-out-aru6-7c63de27.mp3\", \"/storage/v1/object/public/pronunciation/v2/figure-out-aru10-7c63de27.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/figure-out-aru9-7c63de27.mp3\", \"/storage/v1/object/public/pronunciation/v2/figure-out-aru3-7c63de27.mp3\", \"/storage/v1/object/public/pronunciation/v2/figure-out-aru7-7c63de27.mp3\", \"/storage/v1/object/public/pronunciation/v2/figure-out-aru8-7c63de27.mp3\", \"/storage/v1/obj