('78fcd264-445f-5ce7-b749-72c4e12f3569', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '09f1d27d-1950-545a-86bf-26ddd038fd16', 'a6fee9f7-e500-567e-8765-7a053179be07', 'positive', 'UK: /ˈpɒzətɪv/ | US: /ˈpɑːzətɪv/', 'A2', 'adjective', 'tích cực', 'showing confidence, optimism, or expressing agreement and approval in a situation.', 'We received positive feedback from our clients.', 'Chúng tôi đã nhận được phản hồi tích cực từ khách hàng.', '{\"en\": \"The marketing campaign received overwhelmingly positive feedback from corporate client accounts.\", \"vi\": \"Chiến dịch tiếp thị đã nhận được phản hồi vô cùng tích cực từ các tài khoản khách hàng doanh nghiệp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/positive-ljspeech-c4c6c572.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/positive-cori-c4c6c572.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/positive-1ddff9d8.webp', '[\"favorable\", \"optimistic\", \"encouraging\", \"affirmative\"]', '[\"negative\", \"pessimistic\"]', '[{\"phrase\": \"positive feedback\", \"meaning\": \"phản hồi tích cực\"}, {\"phrase\": \"positive attitude\", \"meaning\": \"thái độ tích cực\"}]', NULL, '[{\"pos\": \"adverb\", \"word\": \"positively\"}, {\"pos\": \"noun\", \"word\": \"positiveness\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/positive-cori-c4c6c572.mp3\", \"/storage/v1/object/public/pronunciation/v2/positive-aru0-c4c6c572.mp3\", \"/storage/v1/object/public/pronunciation/v2/positive-aru5-c4c6c572.mp3\", \"/storage/v1/object/public/pronunciation/v2/positive-aru6-c4c6c572.mp3\", \"/storage/v1/object/public/pronunciation/v2/positive-aru10-c4c6c572.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/positive-aru9-c4c6c572.mp3\", \"/storage/v1/object/public/pronunciation/v2/positive-aru3-c4c6c572.mp3\", \"/storage/v1/object/public/pronunciation/v2/positive-aru7-c4c6c572.mp3\", \"/storage/v1/object/public/pronunciation/v2/positive-aru8-c4c6c572.mp3\", \"/