('32d6809c-5858-594a-a2fb-5ddc345f39e0', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '0abf469a-8d89-57e9-a522-e818aebce53f', '3866690f-0506-5e8d-97ab-4340674ecb78', 'predict', 'UK: /prɪˈdɪkt/ | US: /prɪˈdɪkt/', 'B1', 'verb', 'dự đoán', 'To say or estimate that a specific event will happen in the future.', 'Experts predict a rise in sales next quarter.', 'Các chuyên gia dự đoán doanh số sẽ tăng trong quý tới.', '{\"en\": \"Analysts predict that the company\'s revenue will grow by 15 percent next quarter.\", \"vi\": \"Các chuyên gia phân tích dự đoán rằng doanh thu của công ty sẽ tăng 15% vào quý tới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/predict-ljspeech-5226c875.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/predict-cori-5226c875.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/predict-e885b86a.webp', '[\"forecast\", \"project\", \"anticipate\", \"foresee\"]', NULL, '[{\"phrase\": \"predict the outcome\", \"meaning\": \"dự đoán kết quả\"}, {\"phrase\": \"difficult to predict\", \"meaning\": \"khó dự đoán\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"prediction\"}, {\"pos\": \"adjective\", \"word\": \"predictable\"}, {\"pos\": \"adverb\", \"word\": \"predictably\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/predict-cori-5226c875.mp3\", \"/storage/v1/object/public/pronunciation/v2/predict-aru0-5226c875.mp3\", \"/storage/v1/object/public/pronunciation/v2/predict-aru5-5226c875.mp3\", \"/storage/v1/object/public/pronunciation/v2/predict-aru6-5226c875.mp3\", \"/storage/v1/object/public/pronunciation/v2/predict-aru10-5226c875.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/predict-aru9-5226c875.mp3\", \"/storage/v1/object/public/pronunciation/v2/predict-aru3-5226c875.mp3\", \"/storage/v1/object/public/pronunciation/v2/predict-aru7-5226c875.mp3\", \"/storage/v1/object/public/pronunciation/v2/predict-aru8-5226c875.mp3\", \"/storage/v1/object/public/pronunciation/v2/predict-aru2-5