('9c8e2aa1-82a1-5965-87d5-095dac7db1ad', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '0dd92e15-e283-5a2f-80cd-407bba9a7590', '2f16ffcd-a58d-5a20-b7d9-ea0327708df5', 'sign in', 'UK: /saɪn ɪn/ | US: /saɪn ɪn/', 'A2', 'v.phr', 'đăng nhập', 'To enter credentials into a computer program to gain authorized system access.', 'Please sign in to access your account.', 'Vui lòng đăng nhập để truy cập tài khoản của bạn.', '{\"en\": \"All visitors must sign in at the reception desk before entering the building.\", \"vi\": \"Tất cả khách tham quan phải đăng ký / ghi tên tại bàn lễ tân trước khi vào tòa nhà.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/sign-in-ljspeech-44922d1d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/sign-in-cori-44922d1d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/sign-in-b77b050d.webp', '[\"log in\", \"log on\"]', '[\"sign out\", \"log out\"]', '[{\"phrase\": \"sign in to an account\", \"meaning\": \"đăng nhập vào tài khoản\"}, {\"phrase\": \"sign-in sheet\", \"meaning\": \"tờ giấy điểm danh / đăng ký ra vào\"}]', '[{\"word\": \"sign up\", \"note_vi\": \"sign in là đăng nhập/điểm danh vào hệ thống, còn sign up là đăng ký tài khoản mới hoặc đăng ký tham gia\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/sign-in-cori-44922d1d.mp3\", \"/storage/v1/object/public/pronunciation/v2/sign-in-aru0-44922d1d.mp3\", \"/storage/v1/object/public/pronunciation/v2/sign-in-aru5-44922d1d.mp3\", \"/storage/v1/object/public/pronunciation/v2/sign-in-aru6-44922d1d.mp3\", \"/storage/v1/object/public/pronunciation/v2/sign-in-aru10-44922d1d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/sign-in-aru9-44922d1d.mp3\", \"/storage/v1/object/public/pronunciation/v2/sign-in-aru3-44922d1d.mp3\", \"/storage/v1/object/public/pronunciation/v2/sign-in-aru7-44922d1d.mp3\", \"/storage/v1/object/public/pronunciation/v2/sign-in-aru8-44922d1d.mp3\", \"/storage/v1/object/public/pronunciation/v2/sign