('b2e9414e-ea95-5748-877e-46bdae73de9b', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '0f4e121c-c7ee-5358-a18e-b58ecb0d2c6a', '996d692f-2d50-5b17-aeef-c7f1cf07f0b9', 'taxicab', 'UK: /ˈtæk.siˌkæb/ | US: /ˈtæk.siˌkæb/', 'B1', 'noun', 'xe taxi', 'A commercial vehicle driven by a hired driver to transport passengers for a fee.', 'I hailed a taxicab to get to the airport quickly.', 'Tôi vẫy một chiếc taxi để đến sân bay nhanh chóng.', '{\"en\": \"Employees can request reimbursement for taxicab fares incurred during business trips.\", \"vi\": \"Nhân viên có thể yêu cầu hoàn trả chi phí đi xe taxi phát sinh trong các chuyến công tác.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/taxicab-ljspeech-89971469.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/taxicab-cori-89971469.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/taxicab-f6de5e17.webp', '[\"cab\", \"taxi\"]', NULL, '[{\"phrase\": \"taxicab fare\", \"meaning\": \"cước phí xe taxi\"}, {\"phrase\": \"hail a taxicab\", \"meaning\": \"vẫy xe taxi\"}]', '[{\"word\": \"tax\", \"note_vi\": \"\'tax\' nghĩa là tiền thuế, không phải phương tiện xe taxi.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/taxicab-cori-89971469.mp3\", \"/storage/v1/object/public/pronunciation/v2/taxicab-aru0-89971469.mp3\", \"/storage/v1/object/public/pronunciation/v2/taxicab-aru5-89971469.mp3\", \"/storage/v1/object/public/pronunciation/v2/taxicab-aru6-89971469.mp3\", \"/storage/v1/object/public/pronunciation/v2/taxicab-aru10-89971469.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/taxicab-aru9-89971469.mp3\", \"/storage/v1/object/public/pronunciation/v2/taxicab-aru3-89971469.mp3\", \"/storage/v1/object/public/pronunciation/v2/taxicab-aru7-89971469.mp3\", \"/storage/v1/object/public/pronunciation/v2/taxicab-aru8-89971469.mp3\", \"/storage/v1/object/public/pronunciation/v2/taxicab-aru2-89971469.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciat