('25bc72aa-9ddb-527e-a8c3-a3832b1ea047', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '1ad28bf7-a913-54fa-a767-9da56b1fba4b', '60ec6ef0-21ee-5719-9bf4-b35d8a2be7bb', 'swallow', '/ˈswɒləʊ/', 'B1', 'noun', 'Hành động đưa thức ăn hoặc đồ uống từ miệng xuống họng.', 'an act of moving food or drink from mouth down the throat.', 'He took a big swallow of water after running the marathon.', 'Anh ấy uống một ngụm nước lớn sau khi chạy marathon.', '{\"en\": \"The waiter took a swallow of juice during the busy lunch shift.\", \"vi\": \"Người phục vụ đã nuốt một ngụm nước ép trong ca trực bận rộn giờ ăn trưa.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/swallow-ljspeech-a74d7c22.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/swallow-cori-a74d7c22.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/swallow-67314a62.webp', '[\"gulp\", \"mouthful\"]', NULL, '[{\"phrase\": \"take a swallow\", \"meaning\": \"nuốt một ngụm\"}, {\"phrase\": \"big swallow\", \"meaning\": \"ngụm lớn\"}, {\"phrase\": \"swallow of water\", \"meaning\": \"ngụm nước\"}]', '[{\"word\": \"swallow\", \"note_vi\": \"danh từ chim én, khác nghĩa hành động nuốt (bird)\"}, {\"word\": \"hollow\", \"note_vi\": \"rỗng, dễ nhầm chính tả\"}]', '[{\"pos\": \"verb\", \"word\": \"swallow\"}, {\"pos\": \"adjective\", \"word\": \"swallowable\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/swallow-cori-a74d7c22.mp3\", \"/storage/v1/object/public/pronunciation/v2/swallow-aru0-a74d7c22.mp3\", \"/storage/v1/object/public/pronunciation/v2/swallow-aru5-a74d7c22.mp3\", \"/storage/v1/object/public/pronunciation/v2/swallow-aru6-a74d7c22.mp3\", \"/storage/v1/object/public/pronunciation/v2/swallow-aru10-a74d7c22.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/swallow-aru9-a74d7c22.mp3\", \"/storage/v1/object/public/pronunciation/v2/swallow-aru3-a74d7c22.mp3\", \"/storage/v1/object/public/pronunciation/v2/swallow-aru7-a74d7c22.mp3\", \"/storage/v1/objec