('ad5706d9-eeec-5a49-a98c-165b1fef75e8', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '2571624e-24cb-5e80-a7e0-6c2982b9059c', 'e2201365-7c4d-5f64-bca9-27a56c37b203', 'partner', 'UK: /ˈpɑːtnə/ | US: /ˈpɑːrtnər/', 'A2', 'noun', 'đối tác', 'an individual or business taking part with another in a shared activity or commercial venture.', 'We are seeking a new business partner.', 'Chúng tôi đang tìm kiếm một đối tác kinh doanh mới.', '{\"en\": \"Our company is seeking a reliable local partner to expand operations into Southeast Asia.\", \"vi\": \"Công ty chúng tôi đang tìm kiếm một đối tác địa phương đáng tin cậy để mở rộng hoạt động sang Đông Nam Á.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/partner-ljspeech-3624db88.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/partner-cori-3624db88.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/partner-2588f432.webp', '[\"collaborator\", \"associate\", \"ally\"]', '[\"rival\", \"competitor\"]', '[{\"phrase\": \"business partner\", \"meaning\": \"đối tác kinh doanh\"}, {\"phrase\": \"strategic partner\", \"meaning\": \"đối tác chiến lược\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"partnership\"}, {\"pos\": \"verb\", \"word\": \"partner\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/partner-cori-3624db88.mp3\", \"/storage/v1/object/public/pronunciation/v2/partner-aru0-3624db88.mp3\", \"/storage/v1/object/public/pronunciation/v2/partner-aru5-3624db88.mp3\", \"/storage/v1/object/public/pronunciation/v2/partner-aru6-3624db88.mp3\", \"/storage/v1/object/public/pronunciation/v2/partner-aru10-3624db88.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/partner-aru9-3624db88.mp3\", \"/storage/v1/object/public/pronunciation/v2/partner-aru3-3624db88.mp3\", \"/storage/v1/object/public/pronunciation/v2/partner-aru7-3624db88.mp3\", \"/storage/v1/object/public/pronunciation/v2/partner-aru8-3624db88.mp3\", \"/storage/v1/object/public/pronunciation/v2/partner-aru