('0b6387cc-3de8-52f0-8ea8-bcfde579f386', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '391ea3c9-ddfe-5135-9422-1af0d4c20f38', '3449ac69-f2d9-501b-a1a6-3bb072609982', 'landmark', '/ˈlændmɑːk/', 'B1', 'noun', 'một địa điểm hoặc công trình nổi bật, dễ nhận biết.', 'a famous building or large object that you can see easily and helps you know where you are.', 'The historic clock tower serves as a prominent landmark for visitors arriving in the town.', 'Tháp đồng hồ lịch sử đóng vai trò như một địa danh nổi bật cho du khách khi đến thị trấn.', '{\"en\": \"The historic hotel is a famous landmark that attracts many tourists to the city center.\", \"vi\": \"Khách sạn lịch sử này là một địa danh nổi tiếng thu hút nhiều khách du lịch đến trung tâm thành phố.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/landmark-ljspeech-93ac1a00.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/landmark-cori-93ac1a00.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/landmark-1beb66a9.webp', '[\"monument\", \"beacon\"]', NULL, '[{\"phrase\": \"historic landmark\", \"meaning\": \"di tích lịch sử\"}, {\"phrase\": \"famous landmark\", \"meaning\": \"địa danh nổi tiếng\"}]', '[{\"word\": \"landscape\", \"note_vi\": \"landscape là phong cảnh, cảnh quan thiên nhiên nói chung\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/landmark-cori-93ac1a00.mp3\", \"/storage/v1/object/public/pronunciation/v2/landmark-aru0-93ac1a00.mp3\", \"/storage/v1/object/public/pronunciation/v2/landmark-aru5-93ac1a00.mp3\", \"/storage/v1/object/public/pronunciation/v2/landmark-aru6-93ac1a00.mp3\", \"/storage/v1/object/public/pronunciation/v2/landmark-aru10-93ac1a00.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/landmark-aru9-93ac1a00.mp3\", \"/storage/v1/object/public/pronunciation/v2/landmark-aru3-93ac1a00.mp3\", \"/storage/v1/object/public/pronunciation/v2/landmark-aru7-93ac1a00.mp3\", \"/storage/v1/object/public/pronunciation/v2/landm