('488b01dd-a3d4-5bfc-b3d2-580a054e3339', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '391ea3c9-ddfe-5135-9422-1af0d4c20f38', '3449ac69-f2d9-501b-a1a6-3bb072609982', 'napkin', 'UK: /ˈnæpkɪn/ | US: /ˈnæpkɪn/', 'B1', 'noun', 'khăn ăn', 'a small piece of cloth or soft paper used during dining to clean hands and mouth.', 'Each diner received a clean napkin.', 'Mỗi thực khách nhận được một chiếc khăn ăn sạch.', '{\"en\": \"The banquet staff folded cloth napkins neatly on top of each dinner plate before guests arrived.\", \"vi\": \"Nhân viên tiệc đã gấp các khăn ăn bằng vải gọn gàng lên trên mỗi đĩa ăn trước khi khách đến.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/napkin-ljspeech-9fbc77dc.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/napkin-cori-9fbc77dc.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/napkin-c3e3e927.webp', '[\"serviette\"]', NULL, '[{\"phrase\": \"paper napkin\", \"meaning\": \"khăn ăn bằng giấy\"}, {\"phrase\": \"cloth napkin\", \"meaning\": \"khăn ăn bằng vải\"}]', '[{\"word\": \"towel\", \"note_vi\": \"khăn lau tay hoặc khăn tắm kích thước lớn hơn\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/napkin-cori-9fbc77dc.mp3\", \"/storage/v1/object/public/pronunciation/v2/napkin-aru0-9fbc77dc.mp3\", \"/storage/v1/object/public/pronunciation/v2/napkin-aru5-9fbc77dc.mp3\", \"/storage/v1/object/public/pronunciation/v2/napkin-aru6-9fbc77dc.mp3\", \"/storage/v1/object/public/pronunciation/v2/napkin-aru10-9fbc77dc.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/napkin-aru9-9fbc77dc.mp3\", \"/storage/v1/object/public/pronunciation/v2/napkin-aru3-9fbc77dc.mp3\", \"/storage/v1/object/public/pronunciation/v2/napkin-aru7-9fbc77dc.mp3\", \"/storage/v1/object/public/pronunciation/v2/napkin-aru8-9fbc77dc.mp3\", \"/storage/v1/object/public/pronunciation/v2/napkin-aru2-9fbc77dc.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/napkin-ljspeech-9fbc77dc.mp3