('c26e0214-51dc-5c67-a555-bfee47dae240', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '391ea3c9-ddfe-5135-9422-1af0d4c20f38', '3449ac69-f2d9-501b-a1a6-3bb072609982', 'due', 'UK: /djuː/ | US: /duː/', 'B1', 'adjective', 'đến hạn, đáo hạn', 'expected or required to happen or be submitted at a designated time.', 'The report is due by Friday afternoon.', 'Báo cáo này đến hạn vào chiều thứ Sáu.', '{\"en\": \"The quarterly financial report is due on Friday afternoon.\", \"vi\": \"Báo cáo tài chính quý đến hạn vào chiều thứ Sáu.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/due-ljspeech-30cdf73e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/due-cori-30cdf73e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/due-b4f4595f.webp', '[\"expected\", \"scheduled\", \"owed\"]', '[\"overdue\"]', '[{\"phrase\": \"be due to\", \"meaning\": \"dự kiến sẽ (làm gì)\"}, {\"phrase\": \"be due on\", \"meaning\": \"đến hạn vào (ngày nào)\"}]', '[{\"word\": \"overdue\", \"note_vi\": \"\'due\' là đến hạn, còn \'overdue\' là đã quá hạn.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/due-cori-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru0-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru5-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru6-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru10-30cdf73e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/due-aru9-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru3-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru7-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru8-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru2-30cdf73e.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/due-ljspeech-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-lt408-30cdf73e.mp3\", \"/storage/v1/object/