('9e38a7e0-17af-568a-813e-b2ee35ef8ea1', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '3b3d989f-8cca-501e-b52e-28011ad32d61', '2e09ac97-0a71-5f58-a443-b5990b9f3f67', 'grassland', '/ˈɡrɑːslænd/', 'B2', 'noun', 'Khu vực rộng lớn được bao phủ chủ yếu bởi cỏ.', 'a large area of open land mainly covered with wild grass.', 'Cattle graze peacefully on the green grassland surrounding the small rural village.', 'Gia súc gặm cỏ một cách thanh bình trên đồng cỏ xanh bao quanh ngôi làng nhỏ ở nông thôn.', '{\"en\": \"The resort offers guided tours through the surrounding grassland for visiting tourists.\", \"vi\": \"Khu nghỉ dưỡng cung cấp các chuyến tham quan có hướng dẫn qua vùng đồng cỏ xung quanh cho du khách.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/grassland-ljspeech-3a3d1a3e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/grassland-cori-3a3d1a3e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/grassland-f9c82645.webp', '[\"prairie\", \"savanna\", \"meadow\"]', NULL, '[{\"phrase\": \"open grassland\", \"meaning\": \"đồng cỏ bao la\"}, {\"phrase\": \"vast grassland\", \"meaning\": \"cánh đồng cỏ rộng lớn\"}]', '[{\"word\": \"pasture\", \"note_vi\": \"pasture là đồng cỏ dùng để thả gia súc gặm cỏ.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/grassland-cori-3a3d1a3e.mp3\", \"/storage/v1/object/public/pronunciation/v2/grassland-aru0-3a3d1a3e.mp3\", \"/storage/v1/object/public/pronunciation/v2/grassland-aru5-3a3d1a3e.mp3\", \"/storage/v1/object/public/pronunciation/v2/grassland-aru6-3a3d1a3e.mp3\", \"/storage/v1/object/public/pronunciation/v2/grassland-aru10-3a3d1a3e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/grassland-aru9-3a3d1a3e.mp3\", \"/storage/v1/object/public/pronunciation/v2/grassland-aru3-3a3d1a3e.mp3\", \"/storage/v1/object/public/pronunciation/v2/grassland-aru7-3a3d1a3e.mp3\", \"/storage/v1/object/public/pronunciation/v2/grassland-aru8-3a3d1a3e.mp3\", \"/storage/