('4be04e47-91a8-573f-9f6e-3406b72c0030', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '3c8a45cd-6754-5eb1-baf8-caa1f49c9ef1', '6f167af3-4d6f-58af-91d6-6dea02aa75a3', 'paragraph', 'UK: /ˈpærəɡrɑːf/ | US: /ˈpærəɡræf/', 'A2', 'noun', 'đoạn văn', 'a distinct section of written text that begins on a new line and focuses on one main idea.', 'Please read the first paragraph of the report.', 'Vui lòng đọc đoạn đầu tiên của báo cáo.', '{\"en\": \"Please review the third paragraph of the contract carefully before signing.\", \"vi\": \"Vui lòng xem kỹ đoạn văn thứ ba của hợp đồng trước khi ký kết.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/paragraph-ljspeech-f416747c.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/paragraph-cori-f416747c.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/paragraph-df81b17d.webp', '[\"section\", \"passage\", \"clause\"]', NULL, '[{\"phrase\": \"opening paragraph\", \"meaning\": \"đoạn văn mở đầu\"}, {\"phrase\": \"concluding paragraph\", \"meaning\": \"đoạn văn kết luận\"}]', '[{\"word\": \"passage\", \"note_vi\": \"Đoạn trích hoặc bài đọc ngắn (có thể gồm nhiều paragraph).\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/paragraph-cori-f416747c.mp3\", \"/storage/v1/object/public/pronunciation/v2/paragraph-aru0-f416747c.mp3\", \"/storage/v1/object/public/pronunciation/v2/paragraph-aru5-f416747c.mp3\", \"/storage/v1/object/public/pronunciation/v2/paragraph-aru6-f416747c.mp3\", \"/storage/v1/object/public/pronunciation/v2/paragraph-aru10-f416747c.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/paragraph-aru9-f416747c.mp3\", \"/storage/v1/object/public/pronunciation/v2/paragraph-aru3-f416747c.mp3\", \"/storage/v1/object/public/pronunciation/v2/paragraph-aru7-f416747c.mp3\", \"/storage/v1/object/public/pronunciation/v2/paragraph-aru8-f416747c.mp3\", \"/storage/v1/object/public/pronunciation/v2/paragraph-aru2-f416747c.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/o