('6f1d28c6-5846-54f8-9650-f79ca9baabde', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '41b11418-3030-54e9-b95c-69a1d0cf8612', 'b2ce7d72-3145-5253-9893-f5191b3dc7d2', 'studio', '/ˈstjuːdiəʊ/', 'B1', 'noun', 'Phòng làm việc hoặc không gian được trang bị cho nghệ sĩ, nhiếp ảnh gia, hoặc sản xuất phim/nhạc.', 'a room where an artist works or where television and music programs are recorded.', 'The artist created her sculptures in a spacious studio.', 'Nghệ sĩ đã tạo ra các tác phẩm điêu khắc của mình trong một studio rộng rãi.', '{\"en\": \"The marketing team rented a professional studio to shoot the new television commercial.\", \"vi\": \"Đội ngũ tiếp thị đã thuê một studio chuyên nghiệp để quay quảng cáo truyền hình mới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/studio-ljspeech-9a12c50f.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/studio-cori-9a12c50f.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/studio-3f937d07.webp', '[\"workshop\", \"atelier\"]', NULL, '[{\"phrase\": \"recording studio\", \"meaning\": \"phòng thu âm\"}, {\"phrase\": \"art studio\", \"meaning\": \"phòng làm việc của họa sĩ\"}]', '[{\"word\": \"study\", \"note_vi\": \"phòng học hoặc phòng làm việc cá nhân tại nhà\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/studio-cori-9a12c50f.mp3\", \"/storage/v1/object/public/pronunciation/v2/studio-aru0-9a12c50f.mp3\", \"/storage/v1/object/public/pronunciation/v2/studio-aru5-9a12c50f.mp3\", \"/storage/v1/object/public/pronunciation/v2/studio-aru6-9a12c50f.mp3\", \"/storage/v1/object/public/pronunciation/v2/studio-aru10-9a12c50f.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/studio-aru9-9a12c50f.mp3\", \"/storage/v1/object/public/pronunciation/v2/studio-aru3-9a12c50f.mp3\", \"/storage/v1/object/public/pronunciation/v2/studio-aru7-9a12c50f.mp3\", \"/storage/v1/object/public/pronunciation/v2/studio-aru8-9a12c50f.mp3\", \"/storage/v1/object/public/pronunciation/v2