('55b9d70a-4e2a-55cc-b932-d8e233276820', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '41b11418-3030-54e9-b95c-69a1d0cf8612', 'b2ce7d72-3145-5253-9893-f5191b3dc7d2', 'mug', 'UK: /mʌɡ/ | US: /mʌɡ/', 'B1', 'noun', 'cốc có quai', 'a large container with a handle used primarily for drinking warm beverages like hot chocolate.', 'She sipped coffee from her favorite mug.', 'Cô ấy nhâm nhi cà phê từ chiếc cốc yêu thích của mình.', '{\"en\": \"The corporate giveaway bundle included a ceramic mug printed with the company logo.\", \"vi\": \"Bộ quà tặng của công ty bao gồm một chiếc cốc sứ có in logo công ty.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/mug-ljspeech-41eceaf7.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/mug-cori-41eceaf7.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/mug-c948d28f.webp', '[\"cup\", \"beaker\"]', NULL, '[{\"phrase\": \"coffee mug\", \"meaning\": \"cốc uống cà phê\"}, {\"phrase\": \"ceramic mug\", \"meaning\": \"cốc bằng gốm sứ\"}]', '[{\"word\": \"jug\", \"note_vi\": \"bình đựng nước lớn có tay cầm và vòi rót\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/mug-cori-41eceaf7.mp3\", \"/storage/v1/object/public/pronunciation/v2/mug-aru0-41eceaf7.mp3\", \"/storage/v1/object/public/pronunciation/v2/mug-aru5-41eceaf7.mp3\", \"/storage/v1/object/public/pronunciation/v2/mug-aru6-41eceaf7.mp3\", \"/storage/v1/object/public/pronunciation/v2/mug-aru10-41eceaf7.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/mug-aru9-41eceaf7.mp3\", \"/storage/v1/object/public/pronunciation/v2/mug-aru3-41eceaf7.mp3\", \"/storage/v1/object/public/pronunciation/v2/mug-aru7-41eceaf7.mp3\", \"/storage/v1/object/public/pronunciation/v2/mug-aru8-41eceaf7.mp3\", \"/storage/v1/object/public/pronunciation/v2/mug-aru2-41eceaf7.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/mug-ljspeech-41eceaf7.mp3\", \"/storage/v1/object/public/pronunciation/v2/mug-lt408-41eceaf7.m