('47561cd7-8fa3-58cb-8511-3f2e23babf42', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '41b11418-3030-54e9-b95c-69a1d0cf8612', 'b2ce7d72-3145-5253-9893-f5191b3dc7d2', 'world war', '/wɜːld wɔː/', 'B1', 'noun', 'Cuộc chiến tranh quy mô toàn cầu, liên quan đến nhiều quốc gia.', 'a major armed conflict involving many countries across the globe.', 'The history books describe the devastating impact of the Second World War.', 'Những cuốn sách lịch sử mô tả tác động tàn khốc của Thế chiến thứ hai.', '{\"en\": \"The manager discussed the economic effects of the world war in the conference.\", \"vi\": \"Người quản lý thảo luận về các tác động kinh tế của cuộc chiến tranh thế giới trong hội nghị.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/world-war-ljspeech-e1287223.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/world-war-cori-e1287223.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/world-war-bf3e6e0d.webp', '[\"global conflict\", \"international confrontation\"]', NULL, '[{\"phrase\": \"world war i\", \"meaning\": \"chiến tranh thế giới thứ nhất\"}, {\"phrase\": \"world war ii\", \"meaning\": \"chiến tranh thế giới thứ hai\"}]', '[{\"word\": \"civil war\", \"note_vi\": \"civil war là chiến tranh trong nước, không quy mô toàn cầu.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/world-war-cori-e1287223.mp3\", \"/storage/v1/object/public/pronunciation/v2/world-war-aru0-e1287223.mp3\", \"/storage/v1/object/public/pronunciation/v2/world-war-aru5-e1287223.mp3\", \"/storage/v1/object/public/pronunciation/v2/world-war-aru6-e1287223.mp3\", \"/storage/v1/object/public/pronunciation/v2/world-war-aru10-e1287223.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/world-war-aru9-e1287223.mp3\", \"/storage/v1/object/public/pronunciation/v2/world-war-aru3-e1287223.mp3\", \"/storage/v1/object/public/pronunciation/v2/world-war-aru7-e1287223.mp3\", \"/storage/v1/object/public/pronunciation/v2/world-war-ar