('04076490-9e8f-5a51-ad4e-46d3308267aa', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '426c2f02-baa2-5cf2-a3bb-e2f3668f4286', '3daf5918-880d-5376-9da2-ae6e9c452727', 'signature', 'UK: /ˈsɪɡnətʃə/ | US: /ˈsɪɡnətʃər/', 'B1', 'noun', 'chữ ký', 'a person\'s written name used on official documents to show agreement or approval.', 'The contract requires your signature to be valid.', 'Hợp đồng yêu cầu chữ ký của bạn để có hiệu lực.', '{\"en\": \"Please obtain the department head\'s signature before submitting the expense report.\", \"vi\": \"Vui lòng xin chữ ký của trưởng bộ phận trước khi nộp báo cáo chi phí.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/signature-ljspeech-fab5f628.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/signature-cori-fab5f628.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/signature-b863f94c.webp', '[\"autograph\", \"endorsement\", \"mark\"]', NULL, '[{\"phrase\": \"digital signature\", \"meaning\": \"chữ ký số\"}, {\"phrase\": \"require a signature\", \"meaning\": \"yêu cầu chữ ký\"}, {\"phrase\": \"authorized signature\", \"meaning\": \"chữ ký của người có thẩm quyền\"}]', '[{\"word\": \"sign\", \"note_vi\": \"sign vừa là động từ \'ký\', vừa là danh từ \'biển báo\', còn signature là danh từ chỉ \'chữ ký\'.\"}]', '[{\"pos\": \"verb\", \"word\": \"sign\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/signature-cori-fab5f628.mp3\", \"/storage/v1/object/public/pronunciation/v2/signature-aru0-fab5f628.mp3\", \"/storage/v1/object/public/pronunciation/v2/signature-aru5-fab5f628.mp3\", \"/storage/v1/object/public/pronunciation/v2/signature-aru6-fab5f628.mp3\", \"/storage/v1/object/public/pronunciation/v2/signature-aru10-fab5f628.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/signature-aru9-fab5f628.mp3\", \"/storage/v1/object/public/pronunciation/v2/signature-aru3-fab5f628.mp3\", \"/storage/v1/object/public/pronunciation/v2/signature-aru7-fab5f628.mp3\", \"/storage/v