('b183354a-ed6a-5869-9cb7-c70cf31569bd', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '426c2f02-baa2-5cf2-a3bb-e2f3668f4286', '3daf5918-880d-5376-9da2-ae6e9c452727', 'login', '/ˈlɒɡɪn/', 'B1', 'noun', 'Hành động hoặc thông tin cần thiết để truy cập một hệ thống máy tính.', 'the set of details used to access a computer system.', 'Please enter your username and password at the login screen.', 'Vui lòng nhập tên người dùng và mật khẩu của bạn tại màn hình đăng nhập.', '{\"en\": \"The employee forgot the login and could not check the schedule.\", \"vi\": \"Nhân viên đã quên thông tin đăng nhập và không thể kiểm tra lịch trình.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/login-ljspeech-2736fab2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/login-cori-2736fab2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/login-41ed9316.webp', '[\"sign-in\", \"credentials\"]', '[\"logout\"]', '[{\"phrase\": \"login screen\", \"meaning\": \"màn hình đăng nhập\"}, {\"phrase\": \"login details\", \"meaning\": \"thông tin đăng nhập\"}, {\"phrase\": \"login page\", \"meaning\": \"trang đăng nhập\"}]', '[{\"word\": \"logon\", \"note_vi\": \"logon cũng nghĩa đăng nhập, thường dùng ít hơn\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/login-cori-2736fab2.mp3\", \"/storage/v1/object/public/pronunciation/v2/login-aru0-2736fab2.mp3\", \"/storage/v1/object/public/pronunciation/v2/login-aru5-2736fab2.mp3\", \"/storage/v1/object/public/pronunciation/v2/login-aru6-2736fab2.mp3\", \"/storage/v1/object/public/pronunciation/v2/login-aru10-2736fab2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/login-aru9-2736fab2.mp3\", \"/storage/v1/object/public/pronunciation/v2/login-aru3-2736fab2.mp3\", \"/storage/v1/object/public/pronunciation/v2/login-aru7-2736fab2.mp3\", \"/storage/v1/object/public/pronunciation/v2/login-aru8-2736fab2.mp3\", \"/storage/v1/object/public/pronunciation/v2/login-aru2-2736fab2.mp3\"]}, \"u