('0bc871b7-4d96-52e5-9d7c-58c82a6cdbb6', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '47356f54-6eb6-5f84-b0ef-a6f86ca9bf8e', 'f4f5d6b3-ca83-5159-80ad-5cadb8ce2339', 'assist', 'UK: /əˈsɪst/ | US: /əˈsɪst/', 'B1', 'verb', 'giúp đỡ, hỗ trợ', 'to help or give support to someone in completing a task or activity', 'I will assist you with your project.', 'Tôi sẽ hỗ trợ bạn với dự án của bạn.', '{\"en\": \"The technician will assist you with setting up the new office equipment.\", \"vi\": \"Kỹ thuật viên sẽ hỗ trợ bạn cài đặt thiết bị văn phòng mới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/assist-ljspeech-e1b83874.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/assist-cori-e1b83874.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/assist-472ee11d.webp', '[\"help\", \"aid\", \"support\", \"facilitate\"]', '[\"hinder\", \"impede\", \"obstruct\"]', '[{\"phrase\": \"assist in/with\", \"meaning\": \"hỗ trợ trong việc gì\"}, {\"phrase\": \"assist customers\", \"meaning\": \"hỗ trợ khách hàng\"}]', '[{\"word\": \"resist\", \"note_vi\": \"kháng cự, chống lại.\"}]', '[{\"pos\": \"noun\", \"word\": \"assistance\"}, {\"pos\": \"noun\", \"word\": \"assistant\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/assist-cori-e1b83874.mp3\", \"/storage/v1/object/public/pronunciation/v2/assist-aru0-e1b83874.mp3\", \"/storage/v1/object/public/pronunciation/v2/assist-aru5-e1b83874.mp3\", \"/storage/v1/object/public/pronunciation/v2/assist-aru6-e1b83874.mp3\", \"/storage/v1/object/public/pronunciation/v2/assist-aru10-e1b83874.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/assist-aru9-e1b83874.mp3\", \"/storage/v1/object/public/pronunciation/v2/assist-aru3-e1b83874.mp3\", \"/storage/v1/object/public/pronunciation/v2/assist-aru7-e1b83874.mp3\", \"/storage/v1/object/public/pronunciation/v2/assist-aru8-e1b83874.mp3\", \"/storage/v1/object/public/pronunciation/v2/assist-aru2-e1b83874.mp3\"]}, \"us\": {\"nu\": [\"/