('3f891389-9b9f-5c27-accc-565e5fb6d1a9', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '487ab82a-aa40-5480-9267-a8f9ffdc02bc', '924c7d35-ee5c-5051-8081-94892b40e66a', 'plug', 'UK: /plʌɡ ɪn/ | US: /plʌɡ ɪn/', 'B1', 'v.phr', 'cắm điện/kết nối (thiết bị)', 'to connect an electrical device to a power source or main supply.', 'Please plug in the new printer.', 'Vui lòng cắm điện cho máy in mới.', '{\"en\": \"Please ensure that the projector is plugged into a power outlet before the presentation.\", \"vi\": \"Vui lòng đảm bảo máy chiếu đã được cắm vào ổ điện trước buổi thuyết trình.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/plug-ljspeech-68560150.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/plug-cori-68560150.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/plug-d2a1c57c.webp', '[\"connect\", \"insert\", \"attach\"]', '[\"unplug\", \"disconnect\"]', '[{\"phrase\": \"plug in\", \"meaning\": \"cắm thiết bị vào nguồn điện\"}, {\"phrase\": \"plug into an outlet\", \"meaning\": \"cắm vào ổ cắm điện\"}]', '[{\"word\": \"unplug\", \"note_vi\": \"\'Unplug\' nghĩa là rút phích cắm điện, ngược nghĩa với \'plug\'.\"}]', '[{\"pos\": \"noun\", \"word\": \"plug\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/plug-cori-68560150.mp3\", \"/storage/v1/object/public/pronunciation/v2/plug-aru0-68560150.mp3\", \"/storage/v1/object/public/pronunciation/v2/plug-aru5-68560150.mp3\", \"/storage/v1/object/public/pronunciation/v2/plug-aru6-68560150.mp3\", \"/storage/v1/object/public/pronunciation/v2/plug-aru10-68560150.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/plug-aru9-68560150.mp3\", \"/storage/v1/object/public/pronunciation/v2/plug-aru3-68560150.mp3\", \"/storage/v1/object/public/pronunciation/v2/plug-aru7-68560150.mp3\", \"/storage/v1/object/public/pronunciation/v2/plug-aru8-68560150.mp3\", \"/storage/v1/object/public/pronunciation/v2/plug-aru2-68560150.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/objec