('0db5cc55-6dab-53de-818f-6c68108344c1', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '52148d24-355c-53e1-a3d5-df3648c8f7da', '19311776-fe1d-5039-bdb0-7d210e957c45', 'text', 'UK: /tɛkst/ | US: /tɛkst/', 'A2', 'verb', 'nhắn tin', 'to send a written message to someone electronically using a mobile phone.', 'I will text you the meeting details.', 'Tôi sẽ nhắn tin cho bạn thông tin chi tiết cuộc họp.', '{\"en\": \"Please text me when you arrive at the client\'s headquarters.\", \"vi\": \"Vui lòng nhắn tin cho tôi khi bạn tới trụ sở của khách hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/text-ljspeech-372ea08c.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/text-cori-372ea08c.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/text-1b2adc31.webp', '[\"message\", \"SMS\"]', NULL, '[{\"phrase\": \"text a client\", \"meaning\": \"nhắn tin cho khách hàng\"}, {\"phrase\": \"text message\", \"meaning\": \"tin nhắn văn bản\"}]', '[{\"word\": \"test\", \"note_vi\": \"bài kiểm tra, việc kiểm thử\"}]', '[{\"pos\": \"noun\", \"word\": \"text\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/text-cori-372ea08c.mp3\", \"/storage/v1/object/public/pronunciation/v2/text-aru0-372ea08c.mp3\", \"/storage/v1/object/public/pronunciation/v2/text-aru5-372ea08c.mp3\", \"/storage/v1/object/public/pronunciation/v2/text-aru6-372ea08c.mp3\", \"/storage/v1/object/public/pronunciation/v2/text-aru10-372ea08c.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/text-aru9-372ea08c.mp3\", \"/storage/v1/object/public/pronunciation/v2/text-aru3-372ea08c.mp3\", \"/storage/v1/object/public/pronunciation/v2/text-aru7-372ea08c.mp3\", \"/storage/v1/object/public/pronunciation/v2/text-aru8-372ea08c.mp3\", \"/storage/v1/object/public/pronunciation/v2/text-aru2-372ea08c.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/text-ljspeech-372ea08c.mp3\", \"/storage/v1/object/public/pronunciation/v2/text-lt408-372ea08c.