('b6ccab07-1867-5d38-85c2-4ac163ca408d', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '52148d24-355c-53e1-a3d5-df3648c8f7da', '19311776-fe1d-5039-bdb0-7d210e957c45', 'term', 'UK: /tɜːm/ | US: /tɜrm/', 'B1', 'noun', 'nhiệm kỳ', 'a fixed or limited period of time during which an official holds office.', 'Her first term as mayor was successful.', 'Nhiệm kỳ đầu tiên làm thị trưởng của cô ấy đã thành công.', '{\"en\": \"The committee chairperson\'s term will expire at the end of the fiscal year.\", \"vi\": \"Nhiệm kỳ của chủ tịch ủy ban sẽ hết hạn vào cuối năm tài chính.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/term-ljspeech-2a4c3b84.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/term-cori-2a4c3b84.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/term-45dcabdc.webp', '[\"period\", \"duration\", \"tenure\"]', NULL, '[{\"phrase\": \"terms and conditions\", \"meaning\": \"các điều khoản và điều kiện\"}, {\"phrase\": \"in the long term\", \"meaning\": \"về mặt lâu dài\"}, {\"phrase\": \"term of contract\", \"meaning\": \"thời hạn hợp đồng\"}]', '[{\"word\": \"team\", \"note_vi\": \"đội, nhóm làm việc\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/term-cori-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru0-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru5-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru6-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru10-2a4c3b84.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/term-aru9-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru3-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru7-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru8-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru2-2a4c3b84.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/term-ljspeech-2a4c3