('1b432ed3-f051-5449-951a-98d4f10258ad', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '56322a68-d531-5a89-9fae-368c98f8b9bd', '99d6c7c6-16a5-5472-8788-de271ad43aa5', 'passcode', 'UK: /ˈpɑːskoʊd/ | US: /ˈpæskoʊd/', 'B1', 'noun', 'mã bảo mật', 'a secret sequence of digits used to gain access to a digital device or system.', 'You need a passcode to unlock your phone.', 'Bạn cần một mã bảo mật để mở khóa điện thoại.', '{\"en\": \"Employees must enter a four-digit passcode to enter the secure server room.\", \"vi\": \"Nhân viên phải nhập mã bảo mật 4 chữ số để vào phòng máy chủ bảo mật.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/passcode-ljspeech-4fcab400.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/passcode-cori-4fcab400.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/passcode-02d1f51a.webp', '[\"PIN\", \"access code\", \"security code\"]', NULL, '[{\"phrase\": \"enter a passcode\", \"meaning\": \"nhập mã bảo mật\"}, {\"phrase\": \"reset passcode\", \"meaning\": \"đặt lại mã bảo mật\"}]', '[{\"word\": \"password\", \"note_vi\": \"Passcode thường chỉ gồm các chữ số, còn password thường kết hợp cả chữ cái và ký tự.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/passcode-cori-4fcab400.mp3\", \"/storage/v1/object/public/pronunciation/v2/passcode-aru0-4fcab400.mp3\", \"/storage/v1/object/public/pronunciation/v2/passcode-aru5-4fcab400.mp3\", \"/storage/v1/object/public/pronunciation/v2/passcode-aru6-4fcab400.mp3\", \"/storage/v1/object/public/pronunciation/v2/passcode-aru10-4fcab400.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/passcode-aru9-4fcab400.mp3\", \"/storage/v1/object/public/pronunciation/v2/passcode-aru3-4fcab400.mp3\", \"/storage/v1/object/public/pronunciation/v2/passcode-aru7-4fcab400.mp3\", \"/storage/v1/object/public/pronunciation/v2/passcode-aru8-4fcab400.mp3\", \"/storage/v1/object/public/pronunciation/v2/passcode-aru2-4fcab400.mp3\"]}, \"us\": {\"nu\": [\"/st