('545e8e4a-7883-52b4-9660-9962654ca12c', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '56322a68-d531-5a89-9fae-368c98f8b9bd', '99d6c7c6-16a5-5472-8788-de271ad43aa5', 'screen', 'UK: /skriːn/ | US: /skriːn/', 'A2', 'noun', 'màn hình', 'a flat display surface on an electronic device where images and text appear.', 'Please share your screen during the presentation.', 'Vui lòng chia sẻ màn hình của bạn trong buổi thuyết trình.', '{\"en\": \"Please adjust your computer screen brightness to reduce eye strain during long working hours.\", \"vi\": \"Vui lòng điều chỉnh độ sáng màn hình máy tính để giảm mỏi mắt trong giờ làm việc kéo dài.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/screen-ljspeech-35b19fa8.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/screen-cori-35b19fa8.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/screen-80a89232.webp', '[\"display\", \"monitor\"]', NULL, '[{\"phrase\": \"touch screen\", \"meaning\": \"màn hình cảm ứng\"}, {\"phrase\": \"screen display\", \"meaning\": \"hiển thị trên màn hình\"}]', '[{\"word\": \"scream\", \"note_vi\": \"\'scream\' có nghĩa là la hét, phát âm khác với \'screen\' (màn hình).\"}]', '[{\"pos\": \"verb\", \"word\": \"screen\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/screen-cori-35b19fa8.mp3\", \"/storage/v1/object/public/pronunciation/v2/screen-aru0-35b19fa8.mp3\", \"/storage/v1/object/public/pronunciation/v2/screen-aru5-35b19fa8.mp3\", \"/storage/v1/object/public/pronunciation/v2/screen-aru6-35b19fa8.mp3\", \"/storage/v1/object/public/pronunciation/v2/screen-aru10-35b19fa8.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/screen-aru9-35b19fa8.mp3\", \"/storage/v1/object/public/pronunciation/v2/screen-aru3-35b19fa8.mp3\", \"/storage/v1/object/public/pronunciation/v2/screen-aru7-35b19fa8.mp3\", \"/storage/v1/object/public/pronunciation/v2/screen-aru8-35b19fa8.mp3\", \"/storage/v1/object/public/pronunciation/v2/screen-aru2-35b19fa8.mp3