('71324f95-e3d8-5093-b5ee-c90f0315c911', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '56322a68-d531-5a89-9fae-368c98f8b9bd', '99d6c7c6-16a5-5472-8788-de271ad43aa5', 'underline', '/ˌʌndəˈlaɪn/', 'B1', 'verb', 'Kẻ một đường bên dưới một từ hoặc câu để nhấn mạnh.', 'to mark text by drawing a straight line underneath it for emphasis.', 'Please underline the key points in your essay.', 'Vui lòng gạch dưới những ý chính trong bài luận của bạn.', '{\"en\": \"Please underline the delivery date on the contract before signing it.\", \"vi\": \"Vui lòng gạch dưới ngày giao hàng trên hợp đồng trước khi ký.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/underline-ljspeech-c82b67c8.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/underline-cori-c82b67c8.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/underline-8e8d2482.webp', '[\"highlight\", \"emphasize\", \"stress\"]', NULL, '[{\"phrase\": \"underline the importance\", \"meaning\": \"nhấn mạnh tầm quan trọng\"}, {\"phrase\": \"underline a word\", \"meaning\": \"gạch dưới một từ\"}]', '[{\"word\": \"underlie\", \"note_vi\": \"nghĩa là làm cơ sở, nền tảng cho cái gì.\"}]', '[{\"pos\": \"noun\", \"word\": \"underline\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/underline-cori-c82b67c8.mp3\", \"/storage/v1/object/public/pronunciation/v2/underline-aru0-c82b67c8.mp3\", \"/storage/v1/object/public/pronunciation/v2/underline-aru5-c82b67c8.mp3\", \"/storage/v1/object/public/pronunciation/v2/underline-aru6-c82b67c8.mp3\", \"/storage/v1/object/public/pronunciation/v2/underline-aru10-c82b67c8.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/underline-aru9-c82b67c8.mp3\", \"/storage/v1/object/public/pronunciation/v2/underline-aru3-c82b67c8.mp3\", \"/storage/v1/object/public/pronunciation/v2/underline-aru7-c82b67c8.mp3\", \"/storage/v1/object/public/pronunciation/v2/underline-aru8-c82b67c8.mp3\", \"/storage/v1/object/public/pronunciation/v2/underline-aru2-c