('3760e6c2-3a31-5aa9-8ef6-80ecdbef2ccf', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '56322a68-d531-5a89-9fae-368c98f8b9bd', '99d6c7c6-16a5-5472-8788-de271ad43aa5', 'payment', 'UK: /ˈpeɪm.ənt/ | US: /ˈpeɪm.ənt/', 'B1', 'noun', 'khoản thanh toán', 'An amount of money given to settle a bill, debt, or commercial transaction.', 'Please make your payment by the due date.', 'Vui lòng thanh toán trước ngày đáo hạn.', '{\"en\": \"Please ensure that your payment is submitted prior to the due date listed on the statement.\", \"vi\": \"Vui lòng đảm bảo rằng khoản thanh toán của bạn được gửi trước ngày đến hạn ghi trên sao kê.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/payment-ljspeech-e86256b2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/payment-cori-e86256b2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/payment-8c8c313f.webp', '[\"remittance\", \"settlement\", \"installment\"]', NULL, '[{\"phrase\": \"payment method\", \"meaning\": \"phương thức thanh toán\"}, {\"phrase\": \"make a payment\", \"meaning\": \"thực hiện thanh toán\"}, {\"phrase\": \"upon payment\", \"meaning\": \"ngay khi thanh toán\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"pay\"}, {\"pos\": \"adjective\", \"word\": \"payable\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/payment-cori-e86256b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/payment-aru0-e86256b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/payment-aru5-e86256b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/payment-aru6-e86256b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/payment-aru10-e86256b2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/payment-aru9-e86256b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/payment-aru3-e86256b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/payment-aru7-e86256b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/payment-aru8-e86256b2.mp3\", \"/storage/v1/object/public/pronunci