('983f61ef-c124-505a-9bdf-fd61c5c7d145', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '5b361965-caad-5cbc-a22c-50880f8ad743', '29c954df-f017-5770-9f99-a5e55af79e7d', 'maximum', 'UK: /ˈmæksɪməm/ | US: /ˈmæksɪməm/', 'B1', 'noun', 'mức tối đa', 'the greatest possible amount, degree, or limit that can be reached or allowed.', 'The maximum capacity of the room is 50 people.', 'Sức chứa tối đa của căn phòng là 50 người.', '{\"en\": \"The project budget has been set to a maximum of $50,000.\", \"vi\": \"Ngân sách dự án đã được ấn định ở mức tối đa là 50.000 USD.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/maximum-ljspeech-e77a3159.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/maximum-cori-e77a3159.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/maximum-0cf29292.webp', '[\"peak\", \"ceiling\", \"upper limit\"]', '[\"minimum\"]', '[{\"phrase\": \"at a maximum\", \"meaning\": \"ở mức tối đa\"}, {\"phrase\": \"reach a maximum\", \"meaning\": \"đạt đến mức tối đa\"}, {\"phrase\": \"to the maximum\", \"meaning\": \"đến mức tối đa\"}]', '[{\"word\": \"maximize\", \"note_vi\": \"maximize là động từ có nghĩa là tối đa hóa\"}]', '[{\"pos\": \"adjective\", \"word\": \"maximum\"}, {\"pos\": \"verb\", \"word\": \"maximize\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/maximum-cori-e77a3159.mp3\", \"/storage/v1/object/public/pronunciation/v2/maximum-aru0-e77a3159.mp3\", \"/storage/v1/object/public/pronunciation/v2/maximum-aru5-e77a3159.mp3\", \"/storage/v1/object/public/pronunciation/v2/maximum-aru6-e77a3159.mp3\", \"/storage/v1/object/public/pronunciation/v2/maximum-aru10-e77a3159.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/maximum-aru9-e77a3159.mp3\", \"/storage/v1/object/public/pronunciation/v2/maximum-aru3-e77a3159.mp3\", \"/storage/v1/object/public/pronunciation/v2/maximum-aru7-e77a3159.mp3\", \"/storage/v1/object/public/pronunciation/v2/maximum-aru8-e77a3159.mp3\", \"/storage/v1/object/p