('76678d7c-2fa7-5a6e-8863-6014c6dd8047', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '5b361965-caad-5cbc-a22c-50880f8ad743', '29c954df-f017-5770-9f99-a5e55af79e7d', 'password', 'UK: /ˈpɑːs.wɜːd/ | US: /ˈpæs.wɝːd/', 'A2', 'noun', 'mật khẩu', 'a secret word or phrase required to gain entry or access to a computer system.', 'You need a password to access your account.', 'Bạn cần mật khẩu để truy cập tài khoản của mình.', '{\"en\": \"For security reasons, employees are advised to change their email passwords every three months.\", \"vi\": \"Vì lý do bảo mật, nhân viên được khuyên nên thay đổi mật khẩu email ba tháng một lần.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/password-ljspeech-5baa61e4.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/password-cori-5baa61e4.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/password-e1369f01.webp', '[\"passcode\", \"access code\", \"login key\"]', NULL, '[{\"phrase\": \"enter a password\", \"meaning\": \"nhập mật khẩu\"}, {\"phrase\": \"password protection\", \"meaning\": \"bảo vệ bằng mật khẩu\"}]', '[{\"word\": \"passcode\", \"note_vi\": \"Password có thể chứa cả chữ cái và ký tự đặc biệt, còn passcode thường là dãy số ngắn.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/password-cori-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru0-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru5-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru6-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru10-5baa61e4.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/password-aru9-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru3-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru7-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru8-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/passwo