('246487f6-2d98-5a3d-9585-109c67c580ea', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '5e074065-244f-56e4-ade2-e04b9f1cd245', '0eb574ba-3b61-572b-acee-b81d4df1a040', 'speedy', '/ˈspiːdi/', 'B2', 'adjective', 'nhanh chóng, khẩn trương', 'happening or done in a short time without any delay.', 'We hope for a speedy recovery for the patient.', 'Chúng tôi hy vọng bệnh nhân sẽ hồi phục nhanh chóng.', '{\"en\": \"Our company promises a speedy delivery service for all online orders this month.\", \"vi\": \"Công ty chúng tôi hứa hẹn dịch vụ giao hàng nhanh chóng cho tất cả đơn hàng trực tuyến tháng này.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/speedy-ljspeech-85895292.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/speedy-cori-85895292.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/speedy-5f2d35e7.webp', '[\"fast\", \"quick\", \"rapid\"]', '[\"slow\", \"sluggish\"]', '[{\"phrase\": \"speedy delivery\", \"meaning\": \"giao hàng nhanh chóng\"}, {\"phrase\": \"speedy recovery\", \"meaning\": \"phục hồi nhanh chóng\"}, {\"phrase\": \"speedy response\", \"meaning\": \"phản hồi nhanh chóng\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"speed\"}, {\"pos\": \"verb\", \"word\": \"speed\"}, {\"pos\": \"adverb\", \"word\": \"speedily\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/speedy-cori-85895292.mp3\", \"/storage/v1/object/public/pronunciation/v2/speedy-aru0-85895292.mp3\", \"/storage/v1/object/public/pronunciation/v2/speedy-aru5-85895292.mp3\", \"/storage/v1/object/public/pronunciation/v2/speedy-aru6-85895292.mp3\", \"/storage/v1/object/public/pronunciation/v2/speedy-aru10-85895292.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/speedy-aru9-85895292.mp3\", \"/storage/v1/object/public/pronunciation/v2/speedy-aru3-85895292.mp3\", \"/storage/v1/object/public/pronunciation/v2/speedy-aru7-85895292.mp3\", \"/storage/v1/object/public/pronunciation/v2/speedy-aru8-85895292.mp3\", \"/storage/v1/obje