('db612b83-6a39-5986-96c6-a2d0fe189597', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '60f8e9a3-6bd3-5105-93b8-6991b1c0594c', '194cd974-88ee-5458-8a3b-28c91cd6fb23', 'boil', '/bɔɪl/', 'B1', 'noun', 'Vết sưng đỏ, đau trên da do nhiễm trùng.', 'a painful, red, and swollen area on the skin caused by a bacterial infection.', 'She had a painful boil on her neck that needed medical attention.', 'Cô ấy có một cái nhọt đau ở cổ cần được chăm sóc y tế.', '{\"en\": \"The employee requested a sick leave because of a painful boil on his arm.\", \"vi\": \"Nhân viên đã xin nghỉ ốm vì một vết sưng đau trên cánh tay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/boil-ljspeech-807a11e7.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/boil-cori-807a11e7.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/boil-989208c3.webp', '[\"abscess\", \"sore\"]', NULL, '[{\"phrase\": \"a painful boil\", \"meaning\": \"một vết sưng đau\"}, {\"phrase\": \"treat a boil\", \"meaning\": \"điều trị vết sưng\"}]', '[{\"word\": \"boil\", \"note_vi\": \"Động từ boil nghĩa là đun sôi, danh từ nghĩa là vết sưng.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/boil-cori-807a11e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/boil-aru0-807a11e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/boil-aru5-807a11e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/boil-aru6-807a11e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/boil-aru10-807a11e7.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/boil-aru9-807a11e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/boil-aru3-807a11e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/boil-aru7-807a11e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/boil-aru8-807a11e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/boil-aru2-807a11e7.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/boil-ljspeech-807a11e7.mp3\", \"/storage/v1/objec