('5e5fdfee-1ab2-508a-ac17-8cedb27acb9b', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '61d9424b-40ab-5a79-aaee-d3e8f7b08141', '4c6135b4-9196-5a35-8df0-394522ca858f', 'straight', '/streɪt/', 'A2', 'adverb', 'Theo một đường thẳng, không cong hay lệch.', 'moving in one direction without turning or bending to the left or right.', 'Please go straight ahead until you reach the traffic lights.', 'Xin hãy đi thẳng về phía trước cho đến khi bạn đến đèn giao thông.', '{\"en\": \"The delivery driver went straight to the warehouse to drop off the urgent shipment.\", \"vi\": \"Người lái xe giao hàng đã đi thẳng đến kho để gửi lô hàng khẩn cấp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/straight-ljspeech-6ec09feb.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/straight-cori-6ec09feb.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/straight-6ca7648d.webp', '[\"directly\", \"undeviatingly\"]', '[\"crookedly\", \"indirectly\"]', '[{\"phrase\": \"go straight\", \"meaning\": \"đi thẳng\"}, {\"phrase\": \"straight away\", \"meaning\": \"ngay lập tức\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"straighten\"}, {\"pos\": \"noun\", \"word\": \"straightness\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/straight-cori-6ec09feb.mp3\", \"/storage/v1/object/public/pronunciation/v2/straight-aru0-6ec09feb.mp3\", \"/storage/v1/object/public/pronunciation/v2/straight-aru5-6ec09feb.mp3\", \"/storage/v1/object/public/pronunciation/v2/straight-aru6-6ec09feb.mp3\", \"/storage/v1/object/public/pronunciation/v2/straight-aru10-6ec09feb.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/straight-aru9-6ec09feb.mp3\", \"/storage/v1/object/public/pronunciation/v2/straight-aru3-6ec09feb.mp3\", \"/storage/v1/object/public/pronunciation/v2/straight-aru7-6ec09feb.mp3\", \"/storage/v1/object/public/pronunciation/v2/straight-aru8-6ec09feb.mp3\", \"/storage/v1/object/public/pronunciation/v2/straight-aru2-6ec09feb.mp3\"]}, \"us\": 