('568cd8ed-a9d0-57f6-9ef7-cd4bca2f702a', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '61d9424b-40ab-5a79-aaee-d3e8f7b08141', '4c6135b4-9196-5a35-8df0-394522ca858f', 'participate', '/pɑːˈtɪsɪpeɪt/', 'B1', 'verb', 'Tham gia vào một hoạt động hoặc sự kiện.', 'to join in or become involved in a shared task or gathering.', 'Everyone is encouraged to participate in the discussion.', 'Mọi người được khuyến khích tham gia vào cuộc thảo luận.', '{\"en\": \"All department heads are required to participate in the annual budget meeting.\", \"vi\": \"Tất cả trưởng phòng được yêu cầu tham gia cuộc họp ngân sách hàng năm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/participate-ljspeech-d6857486.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/participate-cori-d6857486.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/participate-a82a3ead.webp', '[\"take part\", \"engage\", \"join in\"]', '[\"withdraw\", \"abstain\", \"opt out\"]', '[{\"phrase\": \"participate in a meeting\", \"meaning\": \"tham gia cuộc họp\"}, {\"phrase\": \"participate actively\", \"meaning\": \"tham gia tích cực\"}, {\"phrase\": \"participate in a project\", \"meaning\": \"tham gia vào một dự án\"}]', '[{\"word\": \"attend\", \"note_vi\": \"attend chỉ có mặt, participate nhấn mạnh tham gia chủ động\"}]', '[{\"pos\": \"noun\", \"word\": \"participation\"}, {\"pos\": \"noun\", \"word\": \"participant\"}, {\"pos\": \"adjective\", \"word\": \"participatory\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/participate-cori-d6857486.mp3\", \"/storage/v1/object/public/pronunciation/v2/participate-aru0-d6857486.mp3\", \"/storage/v1/object/public/pronunciation/v2/participate-aru5-d6857486.mp3\", \"/storage/v1/object/public/pronunciation/v2/participate-aru6-d6857486.mp3\", \"/storage/v1/object/public/pronunciation/v2/participate-aru10-d6857486.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/participate-aru9-d6857486.mp3\", \"/storage/v1/o