('444e83d1-523e-56aa-976b-fa21af7fca4d', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '6a88767f-ba11-51f8-87cd-9fe26b3c0a3f', '4035c945-0e7b-5f89-a6e2-d6ac48c103e3', 'fast', '/fɑːst/', 'A1', 'adjective', 'Nhanh chóng, tốc độ cao.', 'moving or capable of moving with high speed and quickness.', 'A cheetah is a very fast runner.', 'Báo gêpa là một loài chạy rất nhanh.', '{\"en\": \"The logistics company provides fast shipping services for all domestic commercial orders.\", \"vi\": \"Công ty vận tải cung cấp dịch vụ giao hàng nhanh cho tất cả các đơn hàng thương mại trong nước.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/fast-ljspeech-0afde566.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/fast-cori-0afde566.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/fast-5084aea0.webp', '[\"quick\", \"rapid\", \"swift\"]', '[\"slow\"]', '[{\"phrase\": \"fast delivery\", \"meaning\": \"giao hàng nhanh\"}, {\"phrase\": \"fast pace\", \"meaning\": \"tốc độ nhanh\"}]', '[{\"word\": \"quick\", \"note_vi\": \"fast chỉ tốc độ di chuyển/hành động; quick chỉ thời gian ngắn để hoàn thành.\"}]', '[{\"pos\": \"verb\", \"word\": \"fasten\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/fast-cori-0afde566.mp3\", \"/storage/v1/object/public/pronunciation/v2/fast-aru0-0afde566.mp3\", \"/storage/v1/object/public/pronunciation/v2/fast-aru5-0afde566.mp3\", \"/storage/v1/object/public/pronunciation/v2/fast-aru6-0afde566.mp3\", \"/storage/v1/object/public/pronunciation/v2/fast-aru10-0afde566.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/fast-aru9-0afde566.mp3\", \"/storage/v1/object/public/pronunciation/v2/fast-aru3-0afde566.mp3\", \"/storage/v1/object/public/pronunciation/v2/fast-aru7-0afde566.mp3\", \"/storage/v1/object/public/pronunciation/v2/fast-aru8-0afde566.mp3\", \"/storage/v1/object/public/pronunciation/v2/fast-aru2-0afde566.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/fast-ljs