('d5b1877a-996e-5add-bb3a-6c5241aaa53e', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '736c6ab8-ef30-5a53-a67c-4d9dfd3a6304', '9c17952d-25fe-503a-b76f-efdd60abd3f9', 'lobby', 'UK: /ˈlɒbi/ | US: /ˈlɑːbi/', 'B1', 'noun', 'sảnh chờ', 'a large entrance hall in a hotel, office building, or public venue where visitors wait.', 'Please wait for your appointment in the main lobby.', 'Vui lòng chờ cuộc hẹn của bạn tại sảnh chính.', '{\"en\": \"Visitors are kindly requested to present their identification cards at the reception desk in the main lobby.\", \"vi\": \"Du khách xin vui lòng xuất trình thẻ căn cước tại bàn lễ tân ở sảnh chờ chính.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/lobby-ljspeech-6dc57172.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/lobby-cori-6dc57172.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/lobby-79d1b08f.webp', '[\"foyer\", \"reception area\", \"entrance hall\"]', NULL, '[{\"phrase\": \"hotel lobby\", \"meaning\": \"sảnh khách sạn\"}, {\"phrase\": \"main lobby\", \"meaning\": \"sảnh chính\"}]', '[{\"word\": \"hobby\", \"note_vi\": \"Sở thích cá nhân, phát âm khác với lobby\"}]', '[{\"pos\": \"verb\", \"word\": \"lobby\"}, {\"pos\": \"noun\", \"word\": \"lobbyist\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/lobby-cori-6dc57172.mp3\", \"/storage/v1/object/public/pronunciation/v2/lobby-aru0-6dc57172.mp3\", \"/storage/v1/object/public/pronunciation/v2/lobby-aru5-6dc57172.mp3\", \"/storage/v1/object/public/pronunciation/v2/lobby-aru6-6dc57172.mp3\", \"/storage/v1/object/public/pronunciation/v2/lobby-aru10-6dc57172.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/lobby-aru9-6dc57172.mp3\", \"/storage/v1/object/public/pronunciation/v2/lobby-aru3-6dc57172.mp3\", \"/storage/v1/object/public/pronunciation/v2/lobby-aru7-6dc57172.mp3\", \"/storage/v1/object/public/pronunciation/v2/lobby-aru8-6dc57172.mp3\", \"/storage/v1/object/public/pronunciation/v2/lobby-aru2-6dc57