('030fbccc-0336-5d5e-850b-c74b44a68550', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '7941cc56-14b3-5bb3-8c65-f1ddd698c173', '8418c740-b283-5117-818d-5c92afdf484e', 'province', 'UK: /ˈprɒvɪns/ | US: /ˈprɑːvɪns/', 'B1', 'noun', 'tỉnh', 'an administrative division or territory forming part of a country or empire.', 'Our company has branches in every province.', 'Công ty chúng tôi có chi nhánh ở mọi tỉnh.', '{\"en\": \"The retail chain plans to open five new branch stores in the northern province next month.\", \"vi\": \"Chuỗi bán lẻ có kế hoạch mở 5 cửa hàng chi nhánh mới ở tỉnh phía bắc vào tháng tới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/province-ljspeech-8611a25f.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/province-cori-8611a25f.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/province-3d008fb4.webp', '[\"region\", \"territory\", \"district\", \"state\"]', NULL, '[{\"phrase\": \"northern province\", \"meaning\": \"tỉnh phía bắc\"}, {\"phrase\": \"provincial office\", \"meaning\": \"văn phòng cấp tỉnh\"}, {\"phrase\": \"neighboring province\", \"meaning\": \"tỉnh lân cận\"}]', '[{\"word\": \"provenance\", \"note_vi\": \"Province là tỉnh thành, còn provenance nghĩa là nguồn gốc/xuất xứ của một vật.\"}]', '[{\"pos\": \"adjective\", \"word\": \"provincial\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/province-cori-8611a25f.mp3\", \"/storage/v1/object/public/pronunciation/v2/province-aru0-8611a25f.mp3\", \"/storage/v1/object/public/pronunciation/v2/province-aru5-8611a25f.mp3\", \"/storage/v1/object/public/pronunciation/v2/province-aru6-8611a25f.mp3\", \"/storage/v1/object/public/pronunciation/v2/province-aru10-8611a25f.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/province-aru9-8611a25f.mp3\", \"/storage/v1/object/public/pronunciation/v2/province-aru3-8611a25f.mp3\", \"/storage/v1/object/public/pronunciation/v2/province-aru7-8611a25f.mp3\", \"/storage/v1/object/public/p