('bf72faff-c451-5c11-980f-c081eee2ab10', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '87788b67-1a86-5708-8e13-5fd46069eac6', '39d2a820-1d76-5960-a37c-1b42b726a205', 'teenage', '/ˈtiːneɪdʒ/', 'B1', 'adjective', 'thuộc về hoặc liên quan đến tuổi thiếu niên (13-19 tuổi)', 'relating to people who are between thirteen and nineteen years of age.', 'The concert was popular among the teenage audience.', 'Buổi hòa nhạc rất được khán giả tuổi thiếu niên yêu thích.', '{\"en\": \"The new clothing line is specifically designed to attract the teenage consumer market segment.\", \"vi\": \"Dòng quần áo mới được thiết kế đặc biệt để thu hút phân khúc thị trường người tiêu dùng tuổi thiếu niên.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/teenage-ljspeech-038b2cd4.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/teenage-cori-038b2cd4.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/teenage-495d2797.webp', '[\"adolescent\", \"juvenile\"]', NULL, '[{\"phrase\": \"teenage years\", \"meaning\": \"những năm thiếu niên\"}, {\"phrase\": \"teenage market\", \"meaning\": \"thị trường tuổi thiếu niên\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"teenager\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/teenage-cori-038b2cd4.mp3\", \"/storage/v1/object/public/pronunciation/v2/teenage-aru0-038b2cd4.mp3\", \"/storage/v1/object/public/pronunciation/v2/teenage-aru5-038b2cd4.mp3\", \"/storage/v1/object/public/pronunciation/v2/teenage-aru6-038b2cd4.mp3\", \"/storage/v1/object/public/pronunciation/v2/teenage-aru10-038b2cd4.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/teenage-aru9-038b2cd4.mp3\", \"/storage/v1/object/public/pronunciation/v2/teenage-aru3-038b2cd4.mp3\", \"/storage/v1/object/public/pronunciation/v2/teenage-aru7-038b2cd4.mp3\", \"/storage/v1/object/public/pronunciation/v2/teenage-aru8-038b2cd4.mp3\", \"/storage/v1/object/public/pronunciation/v2/teenage-aru2-038b2cd4.mp3\"]}, \"us\": {\"nu\": [\"/storag