('e89224c4-fd8b-5937-bf47-7e3f017bb188', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '88de92aa-fcf6-53b9-a56d-9186eb241c2f', '4878bcda-e33e-5ff4-a386-93606e8cea5f', 'specific', 'UK: /spəˈsɪfɪk/ | US: /spəˈsɪfɪk/', 'B1', 'adjective', 'cụ thể', 'relating to one particular thing, detail, or situation rather than general ideas', 'We need specific instructions for this task.', 'Chúng tôi cần hướng dẫn cụ thể cho nhiệm vụ này.', '{\"en\": \"Please provide specific guidelines on how to process international refund requests.\", \"vi\": \"Vui lòng cung cấp các hướng dẫn cụ thể về cách xử lý các yêu cầu hoàn tiền quốc tế.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/specific-ljspeech-660cffc2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/specific-cori-660cffc2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/specific-0bb44644.webp', '[\"precise\", \"particular\", \"explicit\", \"exact\"]', '[\"vague\", \"general\", \"indefinite\"]', '[{\"phrase\": \"specific instructions\", \"meaning\": \"hướng dẫn cụ thể\"}, {\"phrase\": \"specific details\", \"meaning\": \"chi tiết cụ thể\"}, {\"phrase\": \"specific requirements\", \"meaning\": \"yêu cầu cụ thể\"}]', '[{\"word\": \"pacific\", \"note_vi\": \"Pacific mang nghĩa hòa bình hoặc Thái Bình Dương, hoàn toàn khác với specific (cụ thể).\"}]', '[{\"pos\": \"adverb\", \"word\": \"specifically\"}, {\"pos\": \"verb\", \"word\": \"specify\"}, {\"pos\": \"noun\", \"word\": \"specification\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/specific-cori-660cffc2.mp3\", \"/storage/v1/object/public/pronunciation/v2/specific-aru0-660cffc2.mp3\", \"/storage/v1/object/public/pronunciation/v2/specific-aru5-660cffc2.mp3\", \"/storage/v1/object/public/pronunciation/v2/specific-aru6-660cffc2.mp3\", \"/storage/v1/object/public/pronunciation/v2/specific-aru10-660cffc2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/specific-aru9-660cffc2.mp3\", \"/storage/v1/object/p