('d5528ec7-457f-5b43-84a0-8ae3ab694b57', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '8aa7a2f1-65bc-5272-bc71-781cf9340043', 'b9acebe9-ddc9-5384-8ffa-34f4dfb51309', 'lamp', 'UK: /læmp/ | US: /læmp/', 'A2', 'noun', 'cái đèn (để bàn, đứng)', 'a device that produces artificial light using electricity, oil, or a flame', 'Please turn on the desk lamp.', 'Làm ơn bật cái đèn bàn lên.', '{\"en\": \"Each workstation is equipped with an adjustable desk lamp to ensure proper illumination.\", \"vi\": \"Mỗi vị trí làm việc đều được trang bị một chiếc đèn bàn điều chỉnh được để đảm bảo đủ độ sáng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/lamp-ljspeech-bc4edcce.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/lamp-cori-bc4edcce.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/lamp-4802929c.webp', '[\"light\", \"lantern\"]', NULL, '[{\"phrase\": \"desk lamp\", \"meaning\": \"đèn bàn\"}, {\"phrase\": \"turn on the lamp\", \"meaning\": \"bật đèn\"}]', '[{\"word\": \"lamb\", \"note_vi\": \"lamb nghĩa là con cừu non, âm \'b\' câm (/læm/).\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/lamp-cori-bc4edcce.mp3\", \"/storage/v1/object/public/pronunciation/v2/lamp-aru0-bc4edcce.mp3\", \"/storage/v1/object/public/pronunciation/v2/lamp-aru5-bc4edcce.mp3\", \"/storage/v1/object/public/pronunciation/v2/lamp-aru6-bc4edcce.mp3\", \"/storage/v1/object/public/pronunciation/v2/lamp-aru10-bc4edcce.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/lamp-aru9-bc4edcce.mp3\", \"/storage/v1/object/public/pronunciation/v2/lamp-aru3-bc4edcce.mp3\", \"/storage/v1/object/public/pronunciation/v2/lamp-aru7-bc4edcce.mp3\", \"/storage/v1/object/public/pronunciation/v2/lamp-aru8-bc4edcce.mp3\", \"/storage/v1/object/public/pronunciation/v2/lamp-aru2-bc4edcce.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/lamp-ljspeech-bc4edcce.mp3\", \"/storage/v1/object/public/pronunciation/v2/lamp-lt408-bc4edcce