('c0df1d42-3c44-555d-afe4-7c82d152c568', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '8aa7a2f1-65bc-5272-bc71-781cf9340043', 'b9acebe9-ddc9-5384-8ffa-34f4dfb51309', 'softly', '/ˈsɒftli/', 'A2', 'adverb', 'một cách nhẹ nhàng, êm ái hoặc không ồn ào.', 'in a quiet, gentle, or not loud manner.', 'Background classical music played softly throughout the elegant hotel lobby.', 'Nhạc cổ điển nền phát nhẹ nhàng khắp sảnh khách sạn sang trọng.', '{\"en\": \"The receptionist spoke softly on the phone to avoid disturbing the clients.\", \"vi\": \"Nhân viên lễ tân nói chuyện nhẹ nhàng qua điện thoại để tránh làm phiền khách hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/softly-ljspeech-8672414c.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/softly-cori-8672414c.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/softly-ba3cb87f.webp', '[\"quietly\", \"gently\", \"mildly\"]', '[\"loudly\", \"harshly\"]', '[{\"phrase\": \"speak softly\", \"meaning\": \"nói khẽ, nói nhẹ nhàng\"}, {\"phrase\": \"tread softly\", \"meaning\": \"bước đi nhẹ nhàng\"}]', NULL, '[{\"pos\": \"adjective\", \"word\": \"soft\"}, {\"pos\": \"noun\", \"word\": \"softness\"}, {\"pos\": \"verb\", \"word\": \"soften\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/softly-cori-8672414c.mp3\", \"/storage/v1/object/public/pronunciation/v2/softly-aru0-8672414c.mp3\", \"/storage/v1/object/public/pronunciation/v2/softly-aru5-8672414c.mp3\", \"/storage/v1/object/public/pronunciation/v2/softly-aru6-8672414c.mp3\", \"/storage/v1/object/public/pronunciation/v2/softly-aru10-8672414c.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/softly-aru9-8672414c.mp3\", \"/storage/v1/object/public/pronunciation/v2/softly-aru3-8672414c.mp3\", \"/storage/v1/object/public/pronunciation/v2/softly-aru7-8672414c.mp3\", \"/storage/v1/object/public/pronunciation/v2/softly-aru8-8672414c.mp3\", \"/storage/v1/object/public/pronunciation/v2/softly-aru2-8672414c.