('cdbe78e4-2a15-5be3-be2d-4c34cbac1057', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '94fd27f3-3921-5071-bc5e-f2385f340b0e', '5a3e130e-6f62-56cb-8db4-7d9b2366207a', 'locally', 'UK: /ˈləʊkəli/ | US: /ˈloʊkəli/', 'B1', 'adverb', 'tại địa phương', 'within a specific nearby area, neighborhood, or community rather than far away or nationwide.', 'The company decided to sell the product locally first.', 'Công ty quyết định bán sản phẩm tại địa phương trước.', '{\"en\": \"All organic vegetables served in the staff cafeteria are grown locally without synthetic fertilizers.\", \"vi\": \"Tất cả rau hữu cơ được phục vụ tại nhà ăn nhân viên đều được trồng tại địa phương mà không dùng phân bón tổng hợp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/locally-ljspeech-22f8dafa.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/locally-cori-22f8dafa.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/locally-9a759b36.webp', '[\"regionally\", \"natively\"]', '[\"globally\", \"internationally\"]', '[{\"phrase\": \"locally sourced\", \"meaning\": \"có nguồn gốc tại địa phương\"}, {\"phrase\": \"produced locally\", \"meaning\": \"được sản xuất tại địa phương\"}]', '[{\"word\": \"vocally\", \"note_vi\": \"Bằng lời nói / phát ngôn, khác với locally\"}]', '[{\"pos\": \"adjective\", \"word\": \"local\"}, {\"pos\": \"noun\", \"word\": \"locality\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/locally-cori-22f8dafa.mp3\", \"/storage/v1/object/public/pronunciation/v2/locally-aru0-22f8dafa.mp3\", \"/storage/v1/object/public/pronunciation/v2/locally-aru5-22f8dafa.mp3\", \"/storage/v1/object/public/pronunciation/v2/locally-aru6-22f8dafa.mp3\", \"/storage/v1/object/public/pronunciation/v2/locally-aru10-22f8dafa.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/locally-aru9-22f8dafa.mp3\", \"/storage/v1/object/public/pronunciation/v2/locally-aru3-22f8dafa.mp3\", \"/storage/v1/object/public/pronunciation/v2/locally-aru7-22f