('cdab67cf-a381-5f0b-814f-d724042bfe08', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '96faf88c-716f-561b-807f-e11fa6a12866', 'e5141d65-dca3-5aa4-ab03-3a91dcb3a870', 'log-on', 'UK: /ˈlɒɡ ɒn/ | US: /ˈlɔɡ ɑn/', 'B1', 'adjective', 'đăng nhập', 'relating to the credentials or information required to gain entry into a computer network.', 'Please enter your log-on details.', 'Vui lòng nhập thông tin đăng nhập của bạn.', '{\"en\": \"New employees will receive their log-on credentials during the IT orientation session.\", \"vi\": \"Nhân viên mới sẽ nhận được thông tin đăng nhập trong buổi hướng dẫn về CNTT.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/log-on-ljspeech-d80bcad6.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/log-on-cori-d80bcad6.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/log-on-7c05c960.webp', '[\"login\", \"sign-in\"]', NULL, '[{\"phrase\": \"log-on details\", \"meaning\": \"thông tin chi tiết đăng nhập\"}, {\"phrase\": \"log-on screen\", \"meaning\": \"màn hình đăng nhập\"}]', '[{\"word\": \"log on\", \"note_vi\": \"Log on là cụm động từ chỉ hành động đăng nhập, không có gạch nối\"}]', '[{\"pos\": \"v.phr\", \"word\": \"log on\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/log-on-cori-d80bcad6.mp3\", \"/storage/v1/object/public/pronunciation/v2/log-on-aru0-d80bcad6.mp3\", \"/storage/v1/object/public/pronunciation/v2/log-on-aru5-d80bcad6.mp3\", \"/storage/v1/object/public/pronunciation/v2/log-on-aru6-d80bcad6.mp3\", \"/storage/v1/object/public/pronunciation/v2/log-on-aru10-d80bcad6.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/log-on-aru9-d80bcad6.mp3\", \"/storage/v1/object/public/pronunciation/v2/log-on-aru3-d80bcad6.mp3\", \"/storage/v1/object/public/pronunciation/v2/log-on-aru7-d80bcad6.mp3\", \"/storage/v1/object/public/pronunciation/v2/log-on-aru8-d80bcad6.mp3\", \"/storage/v1/object/public/pronunciation/v2/log-on-aru2-d80bcad6.mp3\"]}, \"us\": {\"nu\": [\"/s