('1bceb667-3f81-50a5-a293-89269edb377f', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '96faf88c-716f-561b-807f-e11fa6a12866', 'e5141d65-dca3-5aa4-ab03-3a91dcb3a870', 'print', '/prɪnt/', 'B1', 'noun', 'dấu vết, hình in, hoặc mẫu hoa văn trên bề mặt.', 'a mark or pattern made by pressing something onto a surface.', 'The dress had a beautiful floral print.', 'Chiếc váy có một họa tiết hoa rất đẹp.', '{\"en\": \"The fashion company ordered ten rolls of fabric with a modern geometric print.\", \"vi\": \"Công ty thời trang đã đặt hàng mười cuộn vải có họa tiết in hình học hiện đại.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/print-ljspeech-6d0d5876.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/print-cori-6d0d5876.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/print-3c654ddd.webp', '[\"pattern\", \"impression\", \"mark\"]', NULL, '[{\"phrase\": \"floral print\", \"meaning\": \"họa tiết in hoa\"}, {\"phrase\": \"animal print\", \"meaning\": \"họa tiết da thú\"}]', '[{\"word\": \"press\", \"note_vi\": \"press là báo chí hoặc hành động ấn, print là hình in/dấu vết\"}]', '[{\"pos\": \"verb\", \"word\": \"print\"}, {\"pos\": \"noun\", \"word\": \"printer\"}, {\"pos\": \"adjective\", \"word\": \"printable\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/print-cori-6d0d5876.mp3\", \"/storage/v1/object/public/pronunciation/v2/print-aru0-6d0d5876.mp3\", \"/storage/v1/object/public/pronunciation/v2/print-aru5-6d0d5876.mp3\", \"/storage/v1/object/public/pronunciation/v2/print-aru6-6d0d5876.mp3\", \"/storage/v1/object/public/pronunciation/v2/print-aru10-6d0d5876.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/print-aru9-6d0d5876.mp3\", \"/storage/v1/object/public/pronunciation/v2/print-aru3-6d0d5876.mp3\", \"/storage/v1/object/public/pronunciation/v2/print-aru7-6d0d5876.mp3\", \"/storage/v1/object/public/pronunciation/v2/print-aru8-6d0d5876.mp3\", \"/storage/v1/object/public/pronunciation/v2/prin