('d422c3cc-dc21-5efc-8acc-5ea16d8db047', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', '98d338d0-b2a7-511f-a725-2586982f9729', 'fe813c83-4a26-5c7a-850a-d0d915585b87', 'forbid', '/fəˈbɪd/', 'B2', 'verb', 'Ra lệnh không cho phép làm gì.', 'to order someone not to do something, or to make something impossible.', 'The rules explicitly forbid smoking inside the building.', 'Các quy định rõ ràng cấm hút thuốc bên trong tòa nhà.', '{\"en\": \"Company policies strictly forbid employees from using personal phones during working hours.\", \"vi\": \"Các chính sách của công ty nghiêm cấm nhân viên sử dụng điện thoại cá nhân trong giờ làm việc.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/forbid-ljspeech-062b0bd8.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/forbid-cori-062b0bd8.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/forbid-c8e67ed5.webp', '[\"prohibit\", \"ban\", \"disallow\"]', '[\"allow\", \"permit\"]', '[{\"phrase\": \"strictly forbid\", \"meaning\": \"nghiêm cấm\"}, {\"phrase\": \"forbid someone to do something\", \"meaning\": \"cấm ai làm gì\"}]', '[{\"word\": \"prevent\", \"note_vi\": \"prevent là ngăn chặn, forbid là ra lệnh cấm\"}]', '[{\"pos\": \"adjective\", \"word\": \"forbidden\"}, {\"pos\": \"adjective\", \"word\": \"forbidding\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/forbid-cori-062b0bd8.mp3\", \"/storage/v1/object/public/pronunciation/v2/forbid-aru0-062b0bd8.mp3\", \"/storage/v1/object/public/pronunciation/v2/forbid-aru5-062b0bd8.mp3\", \"/storage/v1/object/public/pronunciation/v2/forbid-aru6-062b0bd8.mp3\", \"/storage/v1/object/public/pronunciation/v2/forbid-aru10-062b0bd8.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/forbid-aru9-062b0bd8.mp3\", \"/storage/v1/object/public/pronunciation/v2/forbid-aru3-062b0bd8.mp3\", \"/storage/v1/object/public/pronunciation/v2/forbid-aru7-062b0bd8.mp3\", \"/storage/v1/object/public/pronunciation/v2/forbid-aru8-062b0bd8.mp3\