('9277df7f-7394-5a97-a28f-c55944243380', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'a21e4311-9885-53f6-b05a-7cb932ae0e48', 'b6ce0b86-21d5-50a2-9fb2-9c7739ac17c9', 'station', 'UK: /ˈsteɪʃn/ | US: /ˈsteɪʃn/', 'A2', 'noun', 'nhà ga, trạm', 'a stopping place along a route where passenger trains or buses regularly pick up and set down people.', 'The bus station is near my office.', 'Bến xe buýt gần văn phòng của tôi.', '{\"en\": \"The commuter train arrives at the central station every fifteen minutes during peak morning hours.\", \"vi\": \"Tàu điện đi làm đến nhà ga trung tâm mỗi 15 phút một lần trong giờ cao điểm buổi sáng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/station-ljspeech-2da36ff3.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/station-cori-2da36ff3.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/station-b61c0bcb.webp', '[\"terminal\", \"depot\", \"stop\"]', NULL, '[{\"phrase\": \"train station\", \"meaning\": \"nhà ga xe lửa\"}, {\"phrase\": \"gas station\", \"meaning\": \"trạm xăng\"}]', '[{\"word\": \"stationery\", \"note_vi\": \"văn phòng phẩm (đuôi -ery), khác với station là trạm/nhà ga\"}]', '[{\"pos\": \"verb\", \"word\": \"station\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/station-cori-2da36ff3.mp3\", \"/storage/v1/object/public/pronunciation/v2/station-aru0-2da36ff3.mp3\", \"/storage/v1/object/public/pronunciation/v2/station-aru5-2da36ff3.mp3\", \"/storage/v1/object/public/pronunciation/v2/station-aru6-2da36ff3.mp3\", \"/storage/v1/object/public/pronunciation/v2/station-aru10-2da36ff3.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/station-aru9-2da36ff3.mp3\", \"/storage/v1/object/public/pronunciation/v2/station-aru3-2da36ff3.mp3\", \"/storage/v1/object/public/pronunciation/v2/station-aru7-2da36ff3.mp3\", \"/storage/v1/object/public/pronunciation/v2/station-aru8-2da36ff3.mp3\", \"/storage/v1/object/public/pronunciation/v2/station-aru2-2da36ff3.mp3\"]}, \