('5a14cd6e-ade5-5a2d-b894-87d7dd38b92a', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'a21e4311-9885-53f6-b05a-7cb932ae0e48', 'b6ce0b86-21d5-50a2-9fb2-9c7739ac17c9', 'homemade', '/ˌhəʊm ˈmeɪd/', 'B1', 'adjective', 'Được làm ở nhà chứ không phải ở nhà máy hoặc cửa hàng.', 'produced or prepared in a personal house rather than in a factory.', 'Nothing tastes better than a warm, homemade apple pie.', 'Không gì ngon bằng một chiếc bánh táo ấm nóng, làm tại nhà.', '{\"en\": \"The company cafeteria serves delicious homemade soups and fresh salads every afternoon.\", \"vi\": \"Nhà ăn của công ty phục vụ các món súp tự làm thơm ngon và salad tươi vào mỗi buổi chiều.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/homemade-ljspeech-921c62dd.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/homemade-cori-921c62dd.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/homemade-00386d37.webp', '[\"home-cooked\", \"handmade\"]', '[\"factory-made\", \"commercial\"]', '[{\"phrase\": \"homemade food\", \"meaning\": \"thức ăn tự làm ở nhà\"}, {\"phrase\": \"homemade product\", \"meaning\": \"sản phẩm tự chế\"}]', '[{\"word\": \"handmade\", \"note_vi\": \"Homemade là làm tại nhà (thường là đồ ăn), handmade là làm thủ công bằng tay.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/homemade-cori-921c62dd.mp3\", \"/storage/v1/object/public/pronunciation/v2/homemade-aru0-921c62dd.mp3\", \"/storage/v1/object/public/pronunciation/v2/homemade-aru5-921c62dd.mp3\", \"/storage/v1/object/public/pronunciation/v2/homemade-aru6-921c62dd.mp3\", \"/storage/v1/object/public/pronunciation/v2/homemade-aru10-921c62dd.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/homemade-aru9-921c62dd.mp3\", \"/storage/v1/object/public/pronunciation/v2/homemade-aru3-921c62dd.mp3\", \"/storage/v1/object/public/pronunciation/v2/homemade-aru7-921c62dd.mp3\", \"/storage/v1/object/public/pronunciation/v2/homemade-aru8-921c62dd.mp3\", \"/storage/