('5fcc46fe-dc1d-570a-96ce-7ec36a7c076d', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'a52ff7c4-af0f-54c0-a6f3-7592e28420a5', '0ba0c2cc-94a6-56e4-a267-d7646ebbc5b1', 'forward', 'UK: /ˈfɔːwəd/ | US: /ˈfɔrwərd/', 'B1', 'verb', 'gửi đi, chuyển tiếp', 'To send a received message or document along to another person.', 'Please forward the email to all team members soon.', 'Vui lòng chuyển tiếp email cho tất cả các thành viên trong nhóm sớm.', '{\"en\": \"Could you please forward the signed contract to the accounting department for processing?\", \"vi\": \"Bạn có thể vui lòng chuyển tiếp hợp đồng đã ký tới bộ phận kế toán để xử lý được không?\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/forward-ljspeech-ace0c5e9.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/forward-cori-ace0c5e9.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/forward-287e8960.webp', '[\"send on\", \"redirect\", \"retransmit\", \"pass along\"]', NULL, '[{\"phrase\": \"forward an email\", \"meaning\": \"chuyển tiếp một email\"}, {\"phrase\": \"look forward to\", \"meaning\": \"trông đợi, mong chờ (theo sau là V-ing / Noun)\"}]', NULL, '[{\"pos\": \"adjective\", \"word\": \"forward\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/forward-cori-ace0c5e9.mp3\", \"/storage/v1/object/public/pronunciation/v2/forward-aru0-ace0c5e9.mp3\", \"/storage/v1/object/public/pronunciation/v2/forward-aru5-ace0c5e9.mp3\", \"/storage/v1/object/public/pronunciation/v2/forward-aru6-ace0c5e9.mp3\", \"/storage/v1/object/public/pronunciation/v2/forward-aru10-ace0c5e9.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/forward-aru9-ace0c5e9.mp3\", \"/storage/v1/object/public/pronunciation/v2/forward-aru3-ace0c5e9.mp3\", \"/storage/v1/object/public/pronunciation/v2/forward-aru7-ace0c5e9.mp3\", \"/storage/v1/object/public/pronunciation/v2/forward-aru8-ace0c5e9.mp3\", \"/storage/v1/object/public/pronunciation/v2/forward-aru2-ace0c5e9.mp3\"]}, \"us\": {\"n