('d11446f3-f11b-5404-a259-c1a3dd249169', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'a69d94d5-3db2-577e-963d-1461e234e68c', 'f596e587-8c93-5159-af50-84c6874780ea', 'hotel', '/həʊˈtel/', 'A1', 'noun', 'tòa nhà cung cấp chỗ ở và dịch vụ cho khách du lịch.', 'a building where guests pay to stay in rooms and receive services.', 'They booked a nice hotel room with a view of the ocean for their vacation.', 'Họ đã đặt một phòng khách sạn đẹp có view biển cho kỳ nghỉ của mình.', '{\"en\": \"The company reserved a hotel near the conference center for all visiting delegates.\", \"vi\": \"Công ty đã đặt một khách sạn gần trung tâm hội nghị cho tất cả các đại biểu đến thăm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/hotel-ljspeech-14e83355.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/hotel-cori-14e83355.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/hotel-971317e2.webp', '[\"inn\", \"lodge\", \"accommodation\"]', NULL, '[{\"phrase\": \"book a hotel\", \"meaning\": \"đặt phòng khách sạn\"}, {\"phrase\": \"hotel reservation\", \"meaning\": \"đặt chỗ khách sạn\"}, {\"phrase\": \"luxury hotel\", \"meaning\": \"khách sạn sang trọng\"}]', '[{\"word\": \"motel\", \"note_vi\": \"motel: khách sạn ven đường dành cho khách đi xe; hotel: khách sạn đầy đủ dịch vụ hơn.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/hotel-cori-14e83355.mp3\", \"/storage/v1/object/public/pronunciation/v2/hotel-aru0-14e83355.mp3\", \"/storage/v1/object/public/pronunciation/v2/hotel-aru5-14e83355.mp3\", \"/storage/v1/object/public/pronunciation/v2/hotel-aru6-14e83355.mp3\", \"/storage/v1/object/public/pronunciation/v2/hotel-aru10-14e83355.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/hotel-aru9-14e83355.mp3\", \"/storage/v1/object/public/pronunciation/v2/hotel-aru3-14e83355.mp3\", \"/storage/v1/object/public/pronunciation/v2/hotel-aru7-14e83355.mp3\", \"/storage/v1/object/public/pronunciation/v2/hotel-aru8-14e