('2ddb5497-602e-5d03-ae19-3138f7dda384', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'b6f85088-0fcf-51aa-ac51-a431d0882781', 'ca025e10-81c5-5cd7-abb3-a6de5dc9e2cd', 'alleviate', '/əˈliːvieɪt/', 'B2', 'verb', 'Làm giảm bớt sự khó chịu, đau đớn hoặc vấn đề.', 'to make something such as pain or a problem less severe or serious.', 'The new medication helped to alleviate her chronic pain significantly.', 'Thuốc mới đã giúp giảm đáng kể cơn đau mãn tính của cô ấy.', '{\"en\": \"The manager introduced flexible hours to alleviate stress among employees.\", \"vi\": \"Người quản lý đã áp dụng giờ làm linh hoạt để giảm bớt căng thẳng cho nhân viên.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/alleviate-ljspeech-1ec8ed23.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/alleviate-cori-1ec8ed23.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/alleviate-777f3977.webp', '[\"relieve\", \"ease\", \"reduce\"]', '[\"worsen\", \"aggravate\"]', '[{\"phrase\": \"alleviate stress\", \"meaning\": \"giảm bớt căng thẳng\"}, {\"phrase\": \"alleviate pain\", \"meaning\": \"làm giảm đau\"}, {\"phrase\": \"alleviate pressure\", \"meaning\": \"giảm bớt áp lực\"}]', '[{\"word\": \"eliminate\", \"note_vi\": \"\"}]', '[{\"pos\": \"noun\", \"word\": \"alleviation\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/alleviate-cori-1ec8ed23.mp3\", \"/storage/v1/object/public/pronunciation/v2/alleviate-aru0-1ec8ed23.mp3\", \"/storage/v1/object/public/pronunciation/v2/alleviate-aru5-1ec8ed23.mp3\", \"/storage/v1/object/public/pronunciation/v2/alleviate-aru6-1ec8ed23.mp3\", \"/storage/v1/object/public/pronunciation/v2/alleviate-aru10-1ec8ed23.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/alleviate-aru9-1ec8ed23.mp3\", \"/storage/v1/object/public/pronunciation/v2/alleviate-aru3-1ec8ed23.mp3\", \"/storage/v1/object/public/pronunciation/v2/alleviate-aru7-1ec8ed23.mp3\", \"/storage/v1/object/public/pronunciation/v2/alleviate-aru