('29f72865-0a97-5169-b297-3970b9af67ee', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'ba1d26cd-4912-55cf-b82f-d24759945c39', '492e3130-16db-5fd3-8116-e0dcd23ad212', 'part-time', 'UK: /ˌpɑːtˈtaɪm/ | US: /ˌpɑrtˈtaɪm/', 'A2', 'adjective', 'bán thời gian', 'involving or working fewer hours than standard full daily or weekly schedule.', 'Many students choose part-time jobs to support their studies.', 'Nhiều sinh viên chọn công việc bán thời gian để hỗ trợ việc học của họ.', '{\"en\": \"The retail store is hiring part-time sales associates for the upcoming holiday season.\", \"vi\": \"Cửa hàng bán lẻ đang tuyển nhân viên bán hàng bán thời gian cho mùa lễ hội sắp tới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/part-time-ljspeech-213c8e83.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/part-time-cori-213c8e83.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/part-time-cf61d3af.webp', '[\"half-time\", \"flexible-hour\", \"temporary\"]', '[\"full-time\"]', '[{\"phrase\": \"part-time position\", \"meaning\": \"vị trí làm việc bán thời gian\"}, {\"phrase\": \"part-time employee\", \"meaning\": \"nhân viên bán thời gian\"}]', '[{\"word\": \"full-time\", \"note_vi\": \"Toàn thời gian (thường 40 giờ/tuần).\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/part-time-cori-213c8e83.mp3\", \"/storage/v1/object/public/pronunciation/v2/part-time-aru0-213c8e83.mp3\", \"/storage/v1/object/public/pronunciation/v2/part-time-aru5-213c8e83.mp3\", \"/storage/v1/object/public/pronunciation/v2/part-time-aru6-213c8e83.mp3\", \"/storage/v1/object/public/pronunciation/v2/part-time-aru10-213c8e83.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/part-time-aru9-213c8e83.mp3\", \"/storage/v1/object/public/pronunciation/v2/part-time-aru3-213c8e83.mp3\", \"/storage/v1/object/public/pronunciation/v2/part-time-aru7-213c8e83.mp3\", \"/storage/v1/object/public/pronunciation/v2/part-time-aru8-213c8e83.mp3\", \"/storage/