('448fe579-7fdb-5b6d-bedc-70d21ecd6eb7', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'bd9b2c5f-69d4-50ce-bbfe-66cafacdebc7', '26681c80-2e9a-53b7-9343-ee21d8d4e339', 'boarding pass', '/bɔːdɪŋ pɑːs/', 'A2', 'noun', 'Thẻ cho phép hành khách lên máy bay hoặc tàu.', 'an official document that gives a passenger permission to enter a plane or ship.', 'Please show your digital boarding pass to the airline staff at gate four.', 'Vui lòng trình thẻ lên máy bay kỹ thuật số của bạn cho nhân viên hãng hàng không tại cửa số bốn.', '{\"en\": \"Please present your boarding pass and passport to the airline agent at gate four.\", \"vi\": \"Vui lòng trình thẻ lên máy bay và hộ chiếu cho nhân viên hãng hàng không tại cửa số bốn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/boarding-pass-ljspeech-a3cfd09d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/boarding-pass-cori-a3cfd09d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/boarding-pass-360cdf7d.webp', '[\"boarding card\", \"ticket\"]', NULL, '[{\"phrase\": \"issue a boarding pass\", \"meaning\": \"cấp thẻ lên máy bay\"}, {\"phrase\": \"electronic boarding pass\", \"meaning\": \"thẻ lên máy bay điện tử\"}]', '[{\"word\": \"passport\", \"note_vi\": \"Passport là hộ chiếu; boarding pass là thẻ lên máy bay.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/boarding-pass-cori-a3cfd09d.mp3\", \"/storage/v1/object/public/pronunciation/v2/boarding-pass-aru0-a3cfd09d.mp3\", \"/storage/v1/object/public/pronunciation/v2/boarding-pass-aru5-a3cfd09d.mp3\", \"/storage/v1/object/public/pronunciation/v2/boarding-pass-aru6-a3cfd09d.mp3\", \"/storage/v1/object/public/pronunciation/v2/boarding-pass-aru10-a3cfd09d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/boarding-pass-aru9-a3cfd09d.mp3\", \"/storage/v1/object/public/pronunciation/v2/boarding-pass-aru3-a3cfd09d.mp3\", \"/storage/v1/object/public/pronunciation/v2/boarding-pass-aru7-a3cfd09d.mp3\", \"/stora