('74922003-a397-50bc-bd32-6d11f7a6bfa0', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'c1b73016-4dae-5e68-ab83-91b80a244823', '28ce885f-2ea9-5294-b544-77806459cabd', 'announcement', 'UK: /əˈnaʊns.mənt/ | US: /əˈnaʊns.mənt/', 'B1', 'noun', 'thông báo', 'a formal public statement giving information about something that has happened or will happen.', 'They made an announcement about the new policy.', 'Họ đã đưa ra một thông báo về chính sách mới.', '{\"en\": \"An important announcement regarding the office relocation will be posted on the intranet today.\", \"vi\": \"Một thông báo quan trọng về việc chuyển văn phòng sẽ được đăng trên mạng nội bộ hôm nay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/announcement-ljspeech-bd633590.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/announcement-cori-bd633590.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/announcement-9e0ad1c8.webp', '[\"notice\", \"statement\", \"declaration\", \"bulletin\"]', NULL, '[{\"phrase\": \"make an announcement\", \"meaning\": \"đưa ra thông báo\"}, {\"phrase\": \"formal announcement\", \"meaning\": \"thông báo chính thức\"}, {\"phrase\": \"public announcement\", \"meaning\": \"thông báo công cộng\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"announce\"}, {\"pos\": \"noun\", \"word\": \"announcer\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/announcement-cori-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru0-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru5-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru6-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru10-bd633590.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/announcement-aru9-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru3-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru7-bd633590.mp3