('3c7a42fe-9a15-50b3-9555-d630a601bbb7', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'c1b73016-4dae-5e68-ab83-91b80a244823', '28ce885f-2ea9-5294-b544-77806459cabd', 'westward', '/ˈwestwəd/', 'B2', 'adverb', 'Theo hướng về phía tây.', 'towards the direction where the sun sets in the evening.', 'The birds flew westward as the sun began to set.', 'Những chú chim bay về phía tây khi mặt trời bắt đầu lặn.', '{\"en\": \"The shipping vessel traveled westward to deliver the goods to the port.\", \"vi\": \"Tàu vận chuyển đã đi về phía tây để giao hàng đến cảng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/westward-ljspeech-e8dfe97b.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/westward-cori-e8dfe97b.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/westward-c52bb2c4.webp', '[\"westwards\", \"westerly\"]', '[\"eastward\"]', '[{\"phrase\": \"travel westward\", \"meaning\": \"di chuyển về phía tây\"}, {\"phrase\": \"look westward\", \"meaning\": \"nhìn về phía tây\"}]', '[{\"word\": \"westwards\", \"note_vi\": \"từ đồng nghĩa, thường dùng trong tiếng Anh-Anh\"}]', '[{\"pos\": \"adjective\", \"word\": \"westward\"}, {\"pos\": \"noun\", \"word\": \"west\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/westward-cori-e8dfe97b.mp3\", \"/storage/v1/object/public/pronunciation/v2/westward-aru0-e8dfe97b.mp3\", \"/storage/v1/object/public/pronunciation/v2/westward-aru5-e8dfe97b.mp3\", \"/storage/v1/object/public/pronunciation/v2/westward-aru6-e8dfe97b.mp3\", \"/storage/v1/object/public/pronunciation/v2/westward-aru10-e8dfe97b.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/westward-aru9-e8dfe97b.mp3\", \"/storage/v1/object/public/pronunciation/v2/westward-aru3-e8dfe97b.mp3\", \"/storage/v1/object/public/pronunciation/v2/westward-aru7-e8dfe97b.mp3\", \"/storage/v1/object/public/pronunciation/v2/westward-aru8-e8dfe97b.mp3\", \"/storage/v1/object/public/pronunciation/v2/westward-aru2-e8dfe97b.mp3\"]}, \"