('071016bb-7b29-5e1f-ab33-e36fcc171918', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'c1deb040-4d4d-56f3-8ebe-de60c9a76317', 'd4495266-3b84-542d-a9bc-5738d434f52d', 'scarf', 'UK: /skɑːf/ | US: /skɑːrf/', 'A2', 'noun', 'khăn quàng cổ', 'a piece of cloth worn around the neck or head for warmth or decoration.', 'She tied a scarf around her neck to keep warm.', 'Cô ấy quàng khăn quanh cổ để giữ ấm.', '{\"en\": \"Employees traveling on business to cold regions are advised to bring a warm scarf.\", \"vi\": \"Nhân viên đi công tác đến các vùng lạnh được khuyên nên mang theo khăn quàng cổ ấm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/scarf-ljspeech-a384cff1.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/scarf-cori-a384cff1.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/scarf-3b25039c.webp', '[\"muffler\", \"wrap\", \"shawl\"]', NULL, '[{\"phrase\": \"silk scarf\", \"meaning\": \"khăn quàng lụa\"}, {\"phrase\": \"wear a scarf\", \"meaning\": \"quàng khăn\"}]', '[{\"word\": \"scare\", \"note_vi\": \"scare có nghĩa là làm hoảng sợ, khác với scarf (khăn quàng cổ).\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/scarf-cori-a384cff1.mp3\", \"/storage/v1/object/public/pronunciation/v2/scarf-aru0-a384cff1.mp3\", \"/storage/v1/object/public/pronunciation/v2/scarf-aru5-a384cff1.mp3\", \"/storage/v1/object/public/pronunciation/v2/scarf-aru6-a384cff1.mp3\", \"/storage/v1/object/public/pronunciation/v2/scarf-aru10-a384cff1.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/scarf-aru9-a384cff1.mp3\", \"/storage/v1/object/public/pronunciation/v2/scarf-aru3-a384cff1.mp3\", \"/storage/v1/object/public/pronunciation/v2/scarf-aru7-a384cff1.mp3\", \"/storage/v1/object/public/pronunciation/v2/scarf-aru8-a384cff1.mp3\", \"/storage/v1/object/public/pronunciation/v2/scarf-aru2-a384cff1.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/scarf-ljspeech-a384cff1.mp3\", \"/storage/v1/ob