('6a5e65b1-4793-56ed-a0c2-0792363a9624', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'c61d76fe-2c58-5f23-b2b7-e0a9b5c9c080', 'a801876b-b621-50b9-aa88-593b5b4cde8f', 'promotion', 'UK: /prəˈməʊʃn/ | US: /prəˈmoʊʃn/', 'B1', 'noun', 'sự thăng chức', 'an advancement to a higher position, rank, or responsibility within a workplace structure', 'She was hoping for a promotion to manager this year.', 'Cô ấy hy vọng được thăng chức lên quản lý trong năm nay.', '{\"en\": \"After five years of dedicated service, he earned a promotion to head of the marketing department.\", \"vi\": \"Sau năm năm cống hiến hết mình, anh ấy đã nhận được sự thăng chức lên làm trưởng phòng tiếp thị.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/promotion-ljspeech-410c25c9.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/promotion-cori-410c25c9.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/promotion-2c8c9788.webp', '[\"advancement\", \"preferment\", \"elevation\", \"upgrade\"]', '[\"demotion\"]', '[{\"phrase\": \"earn a promotion\", \"meaning\": \"được thăng chức\"}, {\"phrase\": \"sales promotion\", \"meaning\": \"chương trình xúc tiến bán hàng\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"promote\"}, {\"pos\": \"adjective\", \"word\": \"promotional\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/promotion-cori-410c25c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/promotion-aru0-410c25c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/promotion-aru5-410c25c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/promotion-aru6-410c25c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/promotion-aru10-410c25c9.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/promotion-aru9-410c25c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/promotion-aru3-410c25c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/promotion-aru7-410c25c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/promotion-aru8-410c25c9