('efd944aa-a0d6-56a9-898c-509696a9f146', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'c61d76fe-2c58-5f23-b2b7-e0a9b5c9c080', 'a801876b-b621-50b9-aa88-593b5b4cde8f', 'certainly', '/ˈsɜːtnli/', 'A2', 'adverb', 'Chắc chắn rồi, nhất định.', 'without doubt; in a way that shows something will definitely happen.', 'He will certainly be at the meeting tomorrow morning.', 'Anh ấy chắc chắn sẽ có mặt tại cuộc họp sáng mai.', '{\"en\": \"We will certainly approve your leave request if the project is on track.\", \"vi\": \"Chúng tôi chắc chắn sẽ duyệt đơn xin nghỉ của bạn nếu dự án đúng tiến độ.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/certainly-ljspeech-2146c08a.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/certainly-cori-2146c08a.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/certainly-46011def.webp', '[\"definitely\", \"surely\", \"undoubtedly\"]', '[\"possibly\"]', '[{\"phrase\": \"certainly true\", \"meaning\": \"chắc chắn đúng\"}, {\"phrase\": \"certainly know\", \"meaning\": \"chắc chắn biết\"}, {\"phrase\": \"certainly help\", \"meaning\": \"chắc chắn giúp\"}]', '[{\"word\": \"curtain\", \"note_vi\": \"curtain là rèm cửa, phát âm gần giống.\"}, {\"word\": \"certain\", \"note_vi\": \"certain là tính từ, certainly là trạng từ.\"}]', '[{\"pos\": \"adjective\", \"word\": \"certain\"}, {\"pos\": \"noun\", \"word\": \"certainty\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/certainly-cori-2146c08a.mp3\", \"/storage/v1/object/public/pronunciation/v2/certainly-aru0-2146c08a.mp3\", \"/storage/v1/object/public/pronunciation/v2/certainly-aru5-2146c08a.mp3\", \"/storage/v1/object/public/pronunciation/v2/certainly-aru6-2146c08a.mp3\", \"/storage/v1/object/public/pronunciation/v2/certainly-aru10-2146c08a.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/certainly-aru9-2146c08a.mp3\", \"/storage/v1/object/public/pronunciation/v2/certainly-aru3-2146c08a.mp3\", \"/storage/v1/object/public/pronu