('b18a3370-b06e-58b3-817e-0fd5f7b80598', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'c6c16da3-9d91-52dc-84c6-154fca4a26af', '5f383099-cf3d-5681-97fa-859dd98dafff', 'ton', '/tʌn/', 'B1', 'noun', 'Đơn vị đo khối lượng bằng 1000 kilogam.', 'a unit of weight equal to one thousand kilograms used for heavy industrial goods.', 'The elephant weighs several tons.', 'Con voi nặng vài tấn.', '{\"en\": \"The shipping company charged us for every ton of steel transported to the construction site.\", \"vi\": \"Công ty vận chuyển đã tính phí chúng tôi cho mỗi tấn thép được vận chuyển đến công trường xây dựng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/ton-ljspeech-5e4b6ad2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/ton-cori-5e4b6ad2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/ton-415466c6.webp', '[\"tonne\"]', NULL, '[{\"phrase\": \"metric ton\", \"meaning\": \"tấn mét\"}, {\"phrase\": \"tons of\", \"meaning\": \"rất nhiều (nghĩa bóng)\"}]', '[{\"word\": \"tonne\", \"note_vi\": \"Tonne là đơn vị đo lường hệ mét, ton là đơn vị đo lường Anh/Mỹ.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/ton-cori-5e4b6ad2.mp3\", \"/storage/v1/object/public/pronunciation/v2/ton-aru0-5e4b6ad2.mp3\", \"/storage/v1/object/public/pronunciation/v2/ton-aru5-5e4b6ad2.mp3\", \"/storage/v1/object/public/pronunciation/v2/ton-aru6-5e4b6ad2.mp3\", \"/storage/v1/object/public/pronunciation/v2/ton-aru10-5e4b6ad2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/ton-aru9-5e4b6ad2.mp3\", \"/storage/v1/object/public/pronunciation/v2/ton-aru3-5e4b6ad2.mp3\", \"/storage/v1/object/public/pronunciation/v2/ton-aru7-5e4b6ad2.mp3\", \"/storage/v1/object/public/pronunciation/v2/ton-aru8-5e4b6ad2.mp3\", \"/storage/v1/object/public/pronunciation/v2/ton-aru2-5e4b6ad2.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/ton-ljspeech-5e4b6ad2.mp3\", \"/storage/v1/object/public/pronunciation/v2/ton-lt408-5