('95111843-0621-5d98-acc3-7939564f6da9', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'c6c16da3-9d91-52dc-84c6-154fca4a26af', '5f383099-cf3d-5681-97fa-859dd98dafff', 'section', 'UK: /ˈsɛkʃən/ | US: /ˈsɛkʃən/', 'B1', 'noun', 'phần, mục', 'one of the distinct parts or divisions that make up a whole object.', 'Please read the introduction section carefully.', 'Vui lòng đọc kỹ phần giới thiệu.', '{\"en\": \"Please fill out your educational background in section three of the job application form.\", \"vi\": \"Vui lòng điền thông tin học vấn của bạn vào phần ba của mẫu đơn xin việc.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/section-ljspeech-20182fbc.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/section-cori-20182fbc.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/section-f76f5fc7.webp', '[\"part\", \"division\", \"segment\"]', '[\"whole\"]', '[{\"phrase\": \"section manager\", \"meaning\": \"trưởng bộ phận\"}, {\"phrase\": \"relevant section\", \"meaning\": \"phần/mục liên quan\"}]', '[{\"word\": \"sector\", \"note_vi\": \"\'sector\' là mảng/lĩnh vực kinh tế lớn, còn \'section\' là phần/mục nhỏ trong một tài liệu hoặc khu vực.\"}]', '[{\"pos\": \"adjective\", \"word\": \"sectional\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/section-cori-20182fbc.mp3\", \"/storage/v1/object/public/pronunciation/v2/section-aru0-20182fbc.mp3\", \"/storage/v1/object/public/pronunciation/v2/section-aru5-20182fbc.mp3\", \"/storage/v1/object/public/pronunciation/v2/section-aru6-20182fbc.mp3\", \"/storage/v1/object/public/pronunciation/v2/section-aru10-20182fbc.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/section-aru9-20182fbc.mp3\", \"/storage/v1/object/public/pronunciation/v2/section-aru3-20182fbc.mp3\", \"/storage/v1/object/public/pronunciation/v2/section-aru7-20182fbc.mp3\", \"/storage/v1/object/public/pronunciation/v2/section-aru8-20182fbc.mp3\", \"/storage/v1/object/public/pronunciation/v2/sec