('09c791ed-6bd6-5c06-bbb0-00b55b98f5aa', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'c6c16da3-9d91-52dc-84c6-154fca4a26af', '5f383099-cf3d-5681-97fa-859dd98dafff', 'logo', 'UK: /ˈləʊɡəʊ/ | US: /ˈloʊɡoʊ/', 'B1', 'noun', 'biểu trưng, lô-gô', 'a graphic symbol or emblem used by a company to identify its products and brand.', 'The company logo represents our brand.', 'Biểu trưng công ty đại diện cho thương hiệu của chúng tôi.', '{\"en\": \"The marketing team proposed a new logo design to modernize the company\'s image.\", \"vi\": \"Đội ngũ tiếp thị đã đề xuất một thiết kế logo mới để hiện đại hóa hình ảnh công ty.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/logo-ljspeech-5807dd60.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/logo-cori-5807dd60.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/logo-9f21c46b.webp', '[\"emblem\", \"symbol\", \"trademark\"]', NULL, '[{\"phrase\": \"company logo\", \"meaning\": \"logo công ty\"}, {\"phrase\": \"redesign a logo\", \"meaning\": \"thiết kế lại logo\"}]', '[{\"word\": \"slogan\", \"note_vi\": \"Slogan là câu khẩu hiệu quảng cáo bằng chữ, logo là biểu tượng hình ảnh\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/logo-cori-5807dd60.mp3\", \"/storage/v1/object/public/pronunciation/v2/logo-aru0-5807dd60.mp3\", \"/storage/v1/object/public/pronunciation/v2/logo-aru5-5807dd60.mp3\", \"/storage/v1/object/public/pronunciation/v2/logo-aru6-5807dd60.mp3\", \"/storage/v1/object/public/pronunciation/v2/logo-aru10-5807dd60.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/logo-aru9-5807dd60.mp3\", \"/storage/v1/object/public/pronunciation/v2/logo-aru3-5807dd60.mp3\", \"/storage/v1/object/public/pronunciation/v2/logo-aru7-5807dd60.mp3\", \"/storage/v1/object/public/pronunciation/v2/logo-aru8-5807dd60.mp3\", \"/storage/v1/object/public/pronunciation/v2/logo-aru2-5807dd60.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/logo-ljsp