('1739ac47-fc76-5a46-957e-8353109cae2d', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'd60bddca-1289-5511-bbee-f91a540eb339', 'c03a5703-8788-5884-8325-324d5f44cac0', 'instructor', 'UK: /ɪnˈstrʌk.tə/ | US: /ɪnˈstrʌk.tər/', 'B1', 'noun', 'giảng viên', 'a person who teaches practical skills or a specific academic subject.', 'The yoga instructor led a challenging class.', 'Giảng viên yoga đã hướng dẫn một lớp học đầy thử thách.', '{\"en\": \"The seminar instructor provided practical tips on how to handle difficult customer inquiries.\", \"vi\": \"Giảng viên hội thảo đã cung cấp các mẹo thực tế về cách xử lý các yêu cầu khó từ khách hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/instructor-ljspeech-5db3005d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/instructor-cori-5db3005d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/instructor-b8aa7ac5.webp', '[\"trainer\", \"teacher\", \"tutor\", \"educator\"]', '[\"student\", \"trainee\"]', '[{\"phrase\": \"certified instructor\", \"meaning\": \"giảng viên có chứng chỉ\"}, {\"phrase\": \"lead instructor\", \"meaning\": \"giảng viên chính\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"instruction\"}, {\"pos\": \"verb\", \"word\": \"instruct\"}, {\"pos\": \"adjective\", \"word\": \"instructional\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/instructor-cori-5db3005d.mp3\", \"/storage/v1/object/public/pronunciation/v2/instructor-aru0-5db3005d.mp3\", \"/storage/v1/object/public/pronunciation/v2/instructor-aru5-5db3005d.mp3\", \"/storage/v1/object/public/pronunciation/v2/instructor-aru6-5db3005d.mp3\", \"/storage/v1/object/public/pronunciation/v2/instructor-aru10-5db3005d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/instructor-aru9-5db3005d.mp3\", \"/storage/v1/object/public/pronunciation/v2/instructor-aru3-5db3005d.mp3\", \"/storage/v1/object/public/pronunciation/v2/instructor-aru7-5db3005d.mp3\", \"/storage/v1/object/public/pronunciatio