('5c689ee0-d426-501d-b978-a6e947e5ba20', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'd9fa20cb-1244-5fc7-bfc9-71b51255b0fb', '7b1c5b5d-d05e-5275-9e75-471f1b0b2e94', 'instruction', 'UK: /ɪnˈstrʌkʃən/ | US: /ɪnˈstrʌkʃən/', 'A2', 'noun', 'hướng dẫn', 'detailed directions telling someone how to do or operate something correctly.', 'Please follow the instructions carefully.', 'Vui lòng làm theo hướng dẫn cẩn thận.', '{\"en\": \"Please read the operating instructions carefully before setting up the new office printer.\", \"vi\": \"Vui lòng đọc kỹ hướng dẫn vận hành trước khi lắp đặt máy in văn phòng mới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/instruction-ljspeech-81529fbd.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/instruction-cori-81529fbd.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/instruction-e3ab1657.webp', '[\"direction\", \"guidance\", \"guideline\", \"order\"]', NULL, '[{\"phrase\": \"follow instructions\", \"meaning\": \"làm theo hướng dẫn\"}, {\"phrase\": \"written instructions\", \"meaning\": \"hướng dẫn bằng văn bản\"}, {\"phrase\": \"detailed instructions\", \"meaning\": \"hướng dẫn chi tiết\"}]', '[{\"word\": \"instrument\", \"note_vi\": \"instrument nghĩa là công cụ hoặc nhạc cụ, không phải hướng dẫn.\"}]', '[{\"pos\": \"verb\", \"word\": \"instruct\"}, {\"pos\": \"adjective\", \"word\": \"instructional\"}, {\"pos\": \"noun\", \"word\": \"instructor\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/instruction-cori-81529fbd.mp3\", \"/storage/v1/object/public/pronunciation/v2/instruction-aru0-81529fbd.mp3\", \"/storage/v1/object/public/pronunciation/v2/instruction-aru5-81529fbd.mp3\", \"/storage/v1/object/public/pronunciation/v2/instruction-aru6-81529fbd.mp3\", \"/storage/v1/object/public/pronunciation/v2/instruction-aru10-81529fbd.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/instruction-aru9-81529fbd.mp3\", \"/storage/v1/object/public/pronunciation/v2/instr