('ddc284f9-184b-58f8-b017-75c1385ae5fc', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'dbc9b2d9-452a-5f0d-bf98-089ea438f358', '79a05286-a666-5aaf-81a0-9b0c63c7521b', 'lack', 'UK: /læk/ | US: /læk/', 'B1', 'verb', 'thiếu', 'to not have enough of something that is needed or desired', 'The project lacks sufficient funding to proceed.', 'Dự án thiếu vốn cần thiết để tiếp tục.', '{\"en\": \"The applicant lacks the necessary management experience required for the senior director position.\", \"vi\": \"Ứng viên còn thiếu kinh nghiệm quản lý cần thiết cho vị trí giám đốc cao cấp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/lack-ljspeech-d6658a9d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/lack-cori-d6658a9d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/lack-74247a63.webp', '[\"need\", \"require\", \"want\"]', '[\"possess\", \"have\", \"provide\"]', '[{\"phrase\": \"lack experience\", \"meaning\": \"thiếu kinh nghiệm\"}, {\"phrase\": \"lack resources\", \"meaning\": \"thiếu nguồn lực\"}]', '[{\"word\": \"leak\", \"note_vi\": \"leak nghĩa là rò rỉ (chất lỏng, thông tin), phát âm /liːk/ khác với lack /læk/.\"}]', '[{\"pos\": \"noun\", \"word\": \"lack\"}, {\"pos\": \"adjective\", \"word\": \"lacking\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/lack-cori-d6658a9d.mp3\", \"/storage/v1/object/public/pronunciation/v2/lack-aru0-d6658a9d.mp3\", \"/storage/v1/object/public/pronunciation/v2/lack-aru5-d6658a9d.mp3\", \"/storage/v1/object/public/pronunciation/v2/lack-aru6-d6658a9d.mp3\", \"/storage/v1/object/public/pronunciation/v2/lack-aru10-d6658a9d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/lack-aru9-d6658a9d.mp3\", \"/storage/v1/object/public/pronunciation/v2/lack-aru3-d6658a9d.mp3\", \"/storage/v1/object/public/pronunciation/v2/lack-aru7-d6658a9d.mp3\", \"/storage/v1/object/public/pronunciation/v2/lack-aru8-d6658a9d.mp3\", \"/storage/v1/object/public/pronunciation/v2/lack-aru2-d665