('9dcaeb7e-c52f-5934-98f4-3904eb3219c3', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'dd6b86a1-a064-5ef1-84f8-17fa532e2848', '5f8f925f-d7ec-5b88-b111-b72972c9e612', 'fasten', 'UK: /ˈfɑːsn̩/ | US: /ˈfæsn̩/', 'B1', 'verb', 'buộc chặt, thắt chặt', 'To close or join together securely two parts of something like a belt.', 'Please fasten your seatbelt before takeoff.', 'Vui lòng thắt dây an toàn trước khi cất cánh.', '{\"en\": \"Passengers are requested to fasten their seatbelts as the aircraft prepares for takeoff.\", \"vi\": \"Hành khách được yêu cầu thắt dây an toàn khi máy bay chuẩn bị cất cánh.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/fasten-ljspeech-8d787ecf.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/fasten-cori-8d787ecf.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/fasten-68f19049.webp', '[\"secure\", \"attach\", \"bind\", \"tie\"]', '[\"unfasten\", \"loosen\", \"untie\"]', '[{\"phrase\": \"fasten seatbelts\", \"meaning\": \"thắt dây an toàn\"}, {\"phrase\": \"fasten securely\", \"meaning\": \"buộc/chốt chặt an toàn\"}]', '[{\"word\": \"hasten\", \"note_vi\": \"hasten nghĩa là thúc giục, làm nhanh lên; khác với fasten là buộc chặt.\"}]', '[{\"pos\": \"noun\", \"word\": \"fastener\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/fasten-cori-8d787ecf.mp3\", \"/storage/v1/object/public/pronunciation/v2/fasten-aru0-8d787ecf.mp3\", \"/storage/v1/object/public/pronunciation/v2/fasten-aru5-8d787ecf.mp3\", \"/storage/v1/object/public/pronunciation/v2/fasten-aru6-8d787ecf.mp3\", \"/storage/v1/object/public/pronunciation/v2/fasten-aru10-8d787ecf.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/fasten-aru9-8d787ecf.mp3\", \"/storage/v1/object/public/pronunciation/v2/fasten-aru3-8d787ecf.mp3\", \"/storage/v1/object/public/pronunciation/v2/fasten-aru7-8d787ecf.mp3\", \"/storage/v1/object/public/pronunciation/v2/fasten-aru8-8d787ecf.mp3\", \"/storage/v1/object/public/pronunciation/v2