('6c72a2cc-6461-5a0c-9c76-8d4420b89aa2', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'ddda6dea-84df-5e4b-8594-907b911cdcaf', '93aef7b5-ba57-533c-a699-8293770889aa', 'ceramic', '/səˈræmɪk/', 'B2', 'adjective', 'Làm từ gốm sứ.', 'made of clay that has been shaped and baked at a high temperature.', 'She collects beautiful ceramic plates from different countries.', 'Cô ấy sưu tập những chiếc đĩa gốm đẹp từ các quốc gia khác nhau.', '{\"en\": \"The gift shop sells beautiful ceramic mugs handcrafted by local artists.\", \"vi\": \"Cửa hàng quà tặng bán những chiếc cốc gốm sứ đẹp mắt được làm thủ công bởi các nghệ sĩ địa phương.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/ceramic-ljspeech-70e88539.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/ceramic-cori-70e88539.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/ceramic-fce8e7e7.webp', '[\"clay\", \"porcelain\"]', NULL, '[{\"phrase\": \"ceramic tiles\", \"meaning\": \"gạch men/gốm\"}, {\"phrase\": \"ceramic tableware\", \"meaning\": \"bộ đồ ăn bằng gốm\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"ceramics\"}, {\"pos\": \"noun\", \"word\": \"ceramist\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/ceramic-cori-70e88539.mp3\", \"/storage/v1/object/public/pronunciation/v2/ceramic-aru0-70e88539.mp3\", \"/storage/v1/object/public/pronunciation/v2/ceramic-aru5-70e88539.mp3\", \"/storage/v1/object/public/pronunciation/v2/ceramic-aru6-70e88539.mp3\", \"/storage/v1/object/public/pronunciation/v2/ceramic-aru10-70e88539.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/ceramic-aru9-70e88539.mp3\", \"/storage/v1/object/public/pronunciation/v2/ceramic-aru3-70e88539.mp3\", \"/storage/v1/object/public/pronunciation/v2/ceramic-aru7-70e88539.mp3\", \"/storage/v1/object/public/pronunciation/v2/ceramic-aru8-70e88539.mp3\", \"/storage/v1/object/public/pronunciation/v2/ceramic-aru2-70e88539.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciatio