('95329769-2d38-51c8-a106-f90deb0d1aa3', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'e04a84ec-5303-5eff-bd3f-4c15883b8965', 'bf577af5-f2b4-5e57-aa02-3e8dc5f1e9e8', 'waste', '/weɪst/', 'A2', 'verb', 'sử dụng một cách không hiệu quả hoặc vô ích.', 'to use something in a way that does not provide any benefit or value.', 'Don\'t waste water; turn off the tap when you\'re brushing your teeth.', 'Đừng lãng phí nước; hãy tắt vòi khi bạn đang đánh răng.', '{\"en\": \"We should not waste company resources on projects that do not generate any profit.\", \"vi\": \"Chúng ta không nên lãng phí nguồn lực công ty vào những dự án không tạo ra lợi nhuận.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/waste-ljspeech-3fcdcb3d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/waste-cori-3fcdcb3d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/waste-14263e1f.webp', '[\"squander\", \"misuse\"]', '[\"save\", \"conserve\"]', '[{\"phrase\": \"waste time\", \"meaning\": \"lãng phí thời gian\"}, {\"phrase\": \"waste money\", \"meaning\": \"lãng phí tiền bạc\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"waste\"}, {\"pos\": \"adjective\", \"word\": \"wasteful\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/waste-cori-3fcdcb3d.mp3\", \"/storage/v1/object/public/pronunciation/v2/waste-aru0-3fcdcb3d.mp3\", \"/storage/v1/object/public/pronunciation/v2/waste-aru5-3fcdcb3d.mp3\", \"/storage/v1/object/public/pronunciation/v2/waste-aru6-3fcdcb3d.mp3\", \"/storage/v1/object/public/pronunciation/v2/waste-aru10-3fcdcb3d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/waste-aru9-3fcdcb3d.mp3\", \"/storage/v1/object/public/pronunciation/v2/waste-aru3-3fcdcb3d.mp3\", \"/storage/v1/object/public/pronunciation/v2/waste-aru7-3fcdcb3d.mp3\", \"/storage/v1/object/public/pronunciation/v2/waste-aru8-3fcdcb3d.mp3\", \"/storage/v1/object/public/pronunciation/v2/waste-aru2-3fcdcb3d.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/publi