('9b7b5c36-4fd2-5ad2-b834-2398192919d7', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'e04a84ec-5303-5eff-bd3f-4c15883b8965', 'bf577af5-f2b4-5e57-aa02-3e8dc5f1e9e8', 'paw', '/pɔː/', 'B1', 'noun', 'bàn chân có móng của động vật có vú như chó, mèo.', 'the foot of an animal that has claws or nails, such as a cat or dog.', 'The cat gently cleaned its paw after walking in the garden.', 'Con mèo nhẹ nhàng làm sạch bàn chân của mình sau khi đi trong vườn.', '{\"en\": \"The pet supply store sells special creams to protect a dog\'s paw from hot pavement.\", \"vi\": \"Cửa hàng cung cấp đồ cho thú cưng bán các loại kem đặc biệt để bảo vệ bàn chân chó khỏi mặt đường nóng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/paw-ljspeech-bc90e227.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/paw-cori-bc90e227.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/paw-4e4a90b5.webp', '[\"foot\"]', NULL, '[{\"phrase\": \"cat\'s paw\", \"meaning\": \"bàn chân mèo\"}, {\"phrase\": \"dog\'s paw\", \"meaning\": \"bàn chân chó\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/paw-cori-bc90e227.mp3\", \"/storage/v1/object/public/pronunciation/v2/paw-aru0-bc90e227.mp3\", \"/storage/v1/object/public/pronunciation/v2/paw-aru5-bc90e227.mp3\", \"/storage/v1/object/public/pronunciation/v2/paw-aru6-bc90e227.mp3\", \"/storage/v1/object/public/pronunciation/v2/paw-aru10-bc90e227.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/paw-aru9-bc90e227.mp3\", \"/storage/v1/object/public/pronunciation/v2/paw-aru3-bc90e227.mp3\", \"/storage/v1/object/public/pronunciation/v2/paw-aru7-bc90e227.mp3\", \"/storage/v1/object/public/pronunciation/v2/paw-aru8-bc90e227.mp3\", \"/storage/v1/object/public/pronunciation/v2/paw-aru2-bc90e227.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/paw-ljspeech-bc90e227.mp3\", \"/storage/v1/object/public/pronunciation/v2/paw-lt408-bc90e227.mp3\", \"/storage/v1/object/publi