('27a896e1-3f2f-5fc1-90cc-7adf67a5ec6d', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'e9193d2b-e30c-5b09-a477-3a95df052b5b', '37a9e4d0-4302-5d46-852e-74fd7cfd8e06', 'terminal', '/ˈtɜːmɪnl/', 'B1', 'noun', 'Khu vực cuối cùng của một tuyến đường hoặc nơi đón/trả khách.', 'a building or area where passengers begin or end their journey.', 'Passengers should arrive at the bus terminal at least fifteen minutes before departure.', 'Hành khách nên đến nhà ga xe buýt ít nhất mười lăm phút trước giờ khởi hành.', '{\"en\": \"The bus terminal was crowded with commuters during the morning rush hour.\", \"vi\": \"Bến xe buýt đông nghịt hành khách trong giờ cao điểm buổi sáng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/terminal-ljspeech-46d551da.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/terminal-cori-46d551da.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/terminal-4ebc4faa.webp', '[\"station\", \"depot\", \"terminus\"]', NULL, '[{\"phrase\": \"airport terminal\", \"meaning\": \"nhà ga sân bay\"}, {\"phrase\": \"bus terminal\", \"meaning\": \"bến xe buýt\"}, {\"phrase\": \"terminal station\", \"meaning\": \"ga cuối\"}]', '[{\"word\": \"terminology\", \"note_vi\": \"nghĩa là thuật ngữ, dễ nhầm chính tả với terminal\"}]', '[{\"pos\": \"verb\", \"word\": \"terminate\"}, {\"pos\": \"noun\", \"word\": \"termination\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/terminal-cori-46d551da.mp3\", \"/storage/v1/object/public/pronunciation/v2/terminal-aru0-46d551da.mp3\", \"/storage/v1/object/public/pronunciation/v2/terminal-aru5-46d551da.mp3\", \"/storage/v1/object/public/pronunciation/v2/terminal-aru6-46d551da.mp3\", \"/storage/v1/object/public/pronunciation/v2/terminal-aru10-46d551da.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/terminal-aru9-46d551da.mp3\", \"/storage/v1/object/public/pronunciation/v2/terminal-aru3-46d551da.mp3\", \"/storage/v1/object/public/pronunciation/v2/terminal-aru7-46d