('0fe29b85-547d-5340-a8e0-d1bd55b3ebfd', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'f1847af7-d792-5c8e-85c1-6b7ab475af29', '186a3080-3097-5966-b75e-fc94322e0674', 'marathon', 'UK: /ˈmærəθən/ | US: /ˈmærəθɑːn/', 'B1', 'noun', 'cuộc đua marathon', 'a long foot race covering a specific distance of about forty-two kilometers.', 'She ran her first marathon last year.', 'Cô ấy đã chạy cuộc đua marathon đầu tiên vào năm ngoái.', '{\"en\": \"Our corporation is proud to sponsor the city’s annual charity marathon this spring.\", \"vi\": \"Tập đoàn chúng tôi tự hào tài trợ cho cuộc đua marathon từ thiện hàng năm của thành phố vào mùa xuân này.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/marathon-ljspeech-f7e04610.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/marathon-cori-f7e04610.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/marathon-d320d8cf.webp', '[\"endurance race\", \"long-distance race\"]', NULL, '[{\"phrase\": \"sponsor a marathon\", \"meaning\": \"tài trợ cho một cuộc đua marathon\"}, {\"phrase\": \"marathon session\", \"meaning\": \"phiên họp/làm việc kéo dài liên tục\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/marathon-cori-f7e04610.mp3\", \"/storage/v1/object/public/pronunciation/v2/marathon-aru0-f7e04610.mp3\", \"/storage/v1/object/public/pronunciation/v2/marathon-aru5-f7e04610.mp3\", \"/storage/v1/object/public/pronunciation/v2/marathon-aru6-f7e04610.mp3\", \"/storage/v1/object/public/pronunciation/v2/marathon-aru10-f7e04610.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/marathon-aru9-f7e04610.mp3\", \"/storage/v1/object/public/pronunciation/v2/marathon-aru3-f7e04610.mp3\", \"/storage/v1/object/public/pronunciation/v2/marathon-aru7-f7e04610.mp3\", \"/storage/v1/object/public/pronunciation/v2/marathon-aru8-f7e04610.mp3\", \"/storage/v1/object/public/pronunciation/v2/marathon-aru2-f7e04610.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciati