('c227e2bc-6cbd-53c0-b479-a2bebe29413c', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'f218c8b7-b979-55c8-89e1-dff5214631f4', 'd5a80234-b62b-5859-a830-c38b7997cce4', 'no later than', '', 'B1', 'phrase', 'không muộn hơn', 'at or before a specified time or date and not after it.', 'Submit your report no later than Friday.', 'Nộp báo cáo của bạn không muộn hơn thứ Sáu.', '{\"en\": \"Please submit your expense report no later than Friday at 5:00 PM.\", \"vi\": \"Vui lòng nộp báo cáo chi phí của bạn không muộn hơn 5:00 chiều Thứ Sáu.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/no-later-than-ljspeech-a4aef4da.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/no-later-than-cori-a4aef4da.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/no-later-than-786d794a.webp', '[\"by\", \"at the latest by\", \"on or before\"]', NULL, '[{\"phrase\": \"no later than Friday\", \"meaning\": \"trễ nhất là thứ Sáu\"}, {\"phrase\": \"submit no later than\", \"meaning\": \"nộp không muộn hơn\"}]', '[{\"word\": \"no sooner than\", \"note_vi\": \"No sooner than nghĩa là ngay khi / không sớm hơn, khác với no later than là muộn nhất vào lúc.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/no-later-than-cori-a4aef4da.mp3\", \"/storage/v1/object/public/pronunciation/v2/no-later-than-aru0-a4aef4da.mp3\", \"/storage/v1/object/public/pronunciation/v2/no-later-than-aru5-a4aef4da.mp3\", \"/storage/v1/object/public/pronunciation/v2/no-later-than-aru6-a4aef4da.mp3\", \"/storage/v1/object/public/pronunciation/v2/no-later-than-aru10-a4aef4da.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/no-later-than-aru9-a4aef4da.mp3\", \"/storage/v1/object/public/pronunciation/v2/no-later-than-aru3-a4aef4da.mp3\", \"/storage/v1/object/public/pronunciation/v2/no-later-than-aru7-a4aef4da.mp3\", \"/storage/v1/object/public/pronunciation/v2/no-later-than-aru8-a4aef4da.mp3\", \"/storage/v1/object/public/pronunciation/v2/no-later-than-ar