('fb72e0b8-c4d1-5f1a-8ddc-d1c4890a9cbc', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'f96d1247-647b-5e58-9798-c07aea668c99', 'b69fd548-640c-59db-b495-1c7a12720e38', 'remove', 'UK: /rɪˈmuːv/ | US: /rɪˈmuːv/', 'B1', 'verb', 'loại bỏ, di chuyển', 'to take something away from the place or position where it is currently located.', 'He will remove the item from the box.', 'Anh ấy sẽ lấy món hàng ra khỏi hộp.', '{\"en\": \"Please remove all personal belongings from your desks prior to the office disinfection.\", \"vi\": \"Vui lòng dọn dẹp tất cả đồ dùng cá nhân khỏi bàn làm việc trước khi tiến hành khử trùng văn phòng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/remove-ljspeech-db998458.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/remove-cori-db998458.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/remove-cf2093f4.webp', '[\"eliminate\", \"delete\", \"clear\", \"take away\"]', '[\"add\", \"insert\", \"attach\"]', '[{\"phrase\": \"remove obstacles\", \"meaning\": \"loại bỏ rào cản\"}, {\"phrase\": \"remove from office\", \"meaning\": \"cách chức/bãi nhiệm\"}]', '[{\"word\": \"relocate\", \"note_vi\": \"Relocate là di dời vị trí trụ sở hay nhân viên sang nơi khác, còn remove là gỡ bỏ/xóa bỏ hẳn.\"}]', '[{\"pos\": \"noun\", \"word\": \"removal\"}, {\"pos\": \"adjective\", \"word\": \"removable\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/remove-cori-db998458.mp3\", \"/storage/v1/object/public/pronunciation/v2/remove-aru0-db998458.mp3\", \"/storage/v1/object/public/pronunciation/v2/remove-aru5-db998458.mp3\", \"/storage/v1/object/public/pronunciation/v2/remove-aru6-db998458.mp3\", \"/storage/v1/object/public/pronunciation/v2/remove-aru10-db998458.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/remove-aru9-db998458.mp3\", \"/storage/v1/object/public/pronunciation/v2/remove-aru3-db998458.mp3\", \"/storage/v1/object/public/pronunciation/v2/remove-aru7-db998458.mp3\", \"/storage/v1/objec