('03187be3-23c8-52d0-81eb-c84b544f92ac', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'fa57be82-fbc0-5419-b53f-3e35055c09a5', '75c7466b-1f0d-52cc-ae99-f6ca5e86ad86', 'soothe', '/suːð/', 'B1', 'verb', 'Làm dịu bớt cảm giác đau đớn, khó chịu hoặc căng thẳng.', 'To gently ease physical discomfort or bring peace to an agitated mind.', 'The warm tea helped to soothe her sore throat.', 'Trà ấm giúp xoa dịu cổ họng đau của cô ấy.', '{\"en\": \"The soft music in the lobby helps to soothe anxious clients waiting for meetings.\", \"vi\": \"Âm nhạc nhẹ nhàng ở sảnh giúp làm dịu những khách hàng lo lắng đang chờ họp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/soothe-ljspeech-04cd7909.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/soothe-cori-04cd7909.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/soothe-c8cc1051.webp', '[\"calm\", \"relieve\"]', '[\"irritate\", \"aggravate\"]', '[{\"phrase\": \"soothe pain\", \"meaning\": \"làm dịu đau\"}, {\"phrase\": \"soothe nerves\", \"meaning\": \"làm dịu thần kinh\"}]', '[{\"word\": \"smooth\", \"note_vi\": \"soothe là làm dịu, smooth là làm phẳng bề mặt.\"}]', '[{\"pos\": \"adjective\", \"word\": \"soothing\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/soothe-cori-04cd7909.mp3\", \"/storage/v1/object/public/pronunciation/v2/soothe-aru0-04cd7909.mp3\", \"/storage/v1/object/public/pronunciation/v2/soothe-aru5-04cd7909.mp3\", \"/storage/v1/object/public/pronunciation/v2/soothe-aru6-04cd7909.mp3\", \"/storage/v1/object/public/pronunciation/v2/soothe-aru10-04cd7909.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/soothe-aru9-04cd7909.mp3\", \"/storage/v1/object/public/pronunciation/v2/soothe-aru3-04cd7909.mp3\", \"/storage/v1/object/public/pronunciation/v2/soothe-aru7-04cd7909.mp3\", \"/storage/v1/object/public/pronunciation/v2/soothe-aru8-04cd7909.mp3\", \"/storage/v1/object/public/pronunciation/v2/soothe-aru2-04cd7909.mp3\"]}, \"us\": {\"nu\": [\"/st