INSERT INTO system_vocabulary_words (id, set_id, topic_id, part_id, word, ipa, cefr, part_of_speech, meaning_vi, definition_en, example_en, example_vi, example_toeic, audio_us, audio_uk, image_url, synonyms, antonyms, phrases, confusables, word_family, audio_voices, note_vi, toeic_topic, difficulty_level, order_index) VALUES
('d6d7f370-43fd-5ffe-ab0e-63bdb6bdc51b', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'fa57be82-fbc0-5419-b53f-3e35055c09a5', '75c7466b-1f0d-52cc-ae99-f6ca5e86ad86', 'quiz', 'UK: /kwɪz/ | US: /kwɪz/', 'A2', 'noun', 'bài kiểm tra ngắn', 'A brief informal test given to evaluate a person\'s knowledge of a subject.', 'The quiz covered the main points of the lesson.', 'Bài kiểm tra ngắn bao gồm các điểm chính của bài học.', '{\"en\": \"New trainees must pass a short safety quiz before operating the machinery.\", \"vi\": \"Các học viên mới phải vượt qua một bài kiểm tra an toàn ngắn trước khi vận hành máy móc.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/quiz-ljspeech-d501d3ec.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/quiz-cori-d501d3ec.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/quiz-63bfd6b0.webp', '[\"test\", \"assessment\", \"short exam\"]', NULL, '[{\"phrase\": \"online quiz\", \"meaning\": \"bài kiểm tra ngắn trực tuyến\"}, {\"phrase\": \"take a quiz\", \"meaning\": \"làm bài kiểm tra ngắn\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"quiz\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/quiz-cori-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-aru0-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-aru5-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-aru6-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-aru10-d501d3ec.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/quiz-aru9-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-aru3-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-aru7-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-aru8-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-aru2-d501d3ec.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/quiz-ljspeech-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-lt408-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-lt138-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-lt624-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-lt396-d501d3ec.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/quiz-lt498-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-lt132-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-lt288-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-lt42-d501d3ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/quiz-lt90-d501d3ec.mp3\"]}}', 'Dạng số nhiều nhân đôi chữ z thành \'quizzes\'. Thường dùng trong bối cảnh đào tạo nội bộ nhân viên.', 'training', 1, 21),
('5e157ab2-188a-5ea3-94a7-3ae777ca3b2b', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'fa57be82-fbc0-5419-b53f-3e35055c09a5', '75c7466b-1f0d-52cc-ae99-f6ca5e86ad86', 'horrified', '/ˈhɒrɪfaɪd/', 'B2', 'adjective', 'bị sốc và sợ hãi tột độ', 'feeling extreme shock, fear, or disgust because of something very bad or unexpected.', 'Passengers were horrified when the engine suddenly stopped working during the flight.', 'Các hành khách đã kinh hoàng khi động cơ đột ngột ngừng hoạt động trong chuyến bay.', '{\"en\": \"The manager was horrified to discover that confidential client data had been leaked online.\", \"vi\": \"Người quản lý bàng hoàng khi phát hiện dữ liệu khách hàng bí mật đã bị rò rỉ trực tuyến.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/horrified-ljspeech-139088e8.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/horrified-cori-139088e8.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/horrified-f9a76710.webp', '[\"appalled\", \"shocked\", \"aghast\"]', '[\"relieved\", \"pleased\", \"delighted\"]', '[{\"phrase\": \"horrified by the news\", \"meaning\": \"bàng hoàng trước tin tức\"}, {\"phrase\": \"look horrified\", \"meaning\": \"trông có vẻ kinh hoàng\"}, {\"phrase\": \"absolutely horrified\", \"meaning\": \"hoàn toàn sốc và sợ hãi\"}]', '[{\"word\": \"terrified\", \"note_vi\": \"terrified thiên về sợ hãi, horrified thiên về sốc và ghê tởm\"}]', '[{\"pos\": \"verb\", \"word\": \"horrify\"}, {\"pos\": \"noun\", \"word\": \"horror\"}, {\"pos\": \"adjective\", \"word\": \"horrifying\"}, {\"pos\": \"adverb\", \"word\": \"horribly\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/horrified-cori-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-aru0-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-aru5-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-aru6-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-aru10-139088e8.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/horrified-aru9-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-aru3-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-aru7-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-aru8-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-aru2-139088e8.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/horrified-ljspeech-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-lt408-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-lt138-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-lt624-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-lt396-139088e8.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/horrified-lt498-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-lt132-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-lt288-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-lt42-139088e8.mp3\", \"/storage/v1/object/public/pronunciation/v2/horrified-lt90-139088e8.mp3\"]}}', 'Horrified diễn tả cảm xúc mạnh hơn surprised; đừng dùng thay cho surprised trong văn cảnh nhẹ.', 'other', 1, 22),
('cda0ad44-eead-5ba3-998e-419a9a9e6509', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'fa57be82-fbc0-5419-b53f-3e35055c09a5', '75c7466b-1f0d-52cc-ae99-f6ca5e86ad86', 'disheartening', '/dɪsˈhɑːtnɪŋ/', 'B2', 'adjective', 'Gây ra cảm giác mất hy vọng, chán nản hoặc thất vọng.', 'making you feel that you have lost hope or confidence about a situation.', 'The repeated failures were disheartening, but she refused to give up.', 'Những thất bại lặp đi lặp lại thật nản lòng, nhưng cô ấy từ chối bỏ cuộc.', '{\"en\": \"It was disheartening to see the sales figures drop significantly during the last fiscal quarter.\", \"vi\": \"Thật nản lòng khi thấy số liệu bán hàng giảm đáng kể trong quý tài chính vừa qua.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/disheartening-ljspeech-33ccff8c.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/disheartening-cori-33ccff8c.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/disheartening-8cb194f6.webp', '[\"discouraging\", \"depressing\"]', '[\"encouraging\", \"inspiring\"]', '[{\"phrase\": \"disheartening news\", \"meaning\": \"tin tức gây nản lòng\"}, {\"phrase\": \"disheartening experience\", \"meaning\": \"trải nghiệm thất vọng\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"dishearten\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/disheartening-cori-33ccff8c.mp3\", \"/storage/v1/object/public/pronunciation/v2/disheartening-aru0-33ccff8c.mp3\", \"/storage/v1/object/public/pronunciation/v2/disheartening-aru5-33ccff8c.mp3\", \"/storage/v1/object/public/pronunciation/v2/disheartening-aru6-33ccff8c.mp3\", \"/storage/v1/object/public/pronunciation/v2/disheartening-aru10-33ccff8c.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/disheartening-aru9-33ccff8c.mp3\", \"/storage/v1/object/public/pronunciation/v2/disheartening-aru3-33ccff8c.mp3\", \"/storage/v1/object/public/pronunciation/v2/disheartening-aru7-33ccff8c.mp3\", \"/storage/v1/object/public/pronunciation/v2/d