('ca159110-56eb-5821-9af1-b9efa0141e87', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'fb7928b7-609f-51e8-a461-2c7efcd09e03', '53fec109-8f5f-5106-ad9b-b95d3c5fc830', 'rotate', '/rəʊˈteɪt/', 'B1', 'verb', 'Xoay quanh một trục hoặc trung tâm.', 'to turn or move in a circle around a central point.', 'The security team will rotate shift assignments every month to maintain peak efficiency.', 'Đội ngũ an ninh sẽ xoay ca làm việc hàng tháng để duy trì hiệu quả cao nhất.', '{\"en\": \"Employees in this department rotate shifts every month to ensure fair work distribution.\", \"vi\": \"Nhân viên trong bộ phận này luân chuyển ca làm việc hàng tháng để đảm bảo phân công công việc công bằng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/rotate-ljspeech-2ac527f1.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/rotate-cori-2ac527f1.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/rotate-72649f10.webp', '[\"revolve\", \"spin\", \"turn\"]', NULL, '[{\"phrase\": \"rotate duties\", \"meaning\": \"luân phiên nhiệm vụ\"}, {\"phrase\": \"rotate shifts\", \"meaning\": \"luân chuyển ca làm việc\"}]', '[{\"word\": \"revolve\", \"note_vi\": \"Rotate là tự xoay quanh trục; revolve là quay quanh vật khác.\"}]', '[{\"pos\": \"noun\", \"word\": \"rotation\"}, {\"pos\": \"adjective\", \"word\": \"rotational\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/rotate-cori-2ac527f1.mp3\", \"/storage/v1/object/public/pronunciation/v2/rotate-aru0-2ac527f1.mp3\", \"/storage/v1/object/public/pronunciation/v2/rotate-aru5-2ac527f1.mp3\", \"/storage/v1/object/public/pronunciation/v2/rotate-aru6-2ac527f1.mp3\", \"/storage/v1/object/public/pronunciation/v2/rotate-aru10-2ac527f1.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/rotate-aru9-2ac527f1.mp3\", \"/storage/v1/object/public/pronunciation/v2/rotate-aru3-2ac527f1.mp3\", \"/storage/v1/object/public/pronunciation/v2/rotate-aru7-2ac527f1.mp3\", \"/storage/v1/object/public/pronu