('ce13b333-365b-55d7-a827-79f02e1f2231', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'fb7928b7-609f-51e8-a461-2c7efcd09e03', '53fec109-8f5f-5106-ad9b-b95d3c5fc830', 'commercial', 'UK: /kəˈmɜːʃəl/ | US: /kəˈmɜrʃəl/', 'B1', 'adjective', 'thương mại', 'relating to the buying and selling of goods and services for profit', 'They are developing a new commercial building.', 'Họ đang phát triển một tòa nhà thương mại mới.', '{\"en\": \"The district has transformed from a quiet neighborhood into a busy commercial hub.\", \"vi\": \"Khu vực này đã biến đổi từ một xóm nhỏ yên tĩnh thành một trung tâm thương mại sầm uất.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/commercial-ljspeech-f8ef5300.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/commercial-cori-f8ef5300.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/commercial-1dbba138.webp', '[\"business-related\", \"mercantile\", \"trade-related\"]', '[\"non-profit\", \"residential\"]', '[{\"phrase\": \"commercial property\", \"meaning\": \"bất động sản thương mại\"}, {\"phrase\": \"commercial break\", \"meaning\": \"thời gian tạm dừng để phát quảng cáo\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"commerce\"}, {\"pos\": \"adverb\", \"word\": \"commercially\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/commercial-cori-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru0-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru5-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru6-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru10-f8ef5300.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/commercial-aru9-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru3-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru7-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru8-f8ef5300.mp3\", \"/stor