('c27f716c-89c2-5309-a02b-b65a01e84a79', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'fc7b95cc-1eb9-5ef4-9632-2ca30d8d27a5', '72530315-221e-55db-8135-bec87cb126a9', 'terrace', 'UK: /ˈtɛrəs/ | US: /ˈtɛrəs/', 'B1', 'noun', 'sân thượng, sân hiên', 'a paved outdoor area adjoining a house used for recreation or relaxation.', 'The restaurant has a beautiful outdoor terrace.', 'Nhà hàng có một sân hiên ngoài trời đẹp.', '{\"en\": \"Hotel guests can enjoy complimentary breakfast on the outdoor terrace overlooking the sea.\", \"vi\": \"Khách lưu trú tại khách sạn có thể thưởng thức bữa sáng miễn phí trên sân hiên ngoài trời nhìn ra biển.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/terrace-ljspeech-2d5f4f20.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/terrace-cori-2d5f4f20.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/terrace-b05683be.webp', '[\"patio\", \"balcony\", \"deck\"]', NULL, '[{\"phrase\": \"outdoor terrace\", \"meaning\": \"sân hiên ngoài trời\"}, {\"phrase\": \"roof terrace\", \"meaning\": \"sân thượng mái\"}, {\"phrase\": \"terrace dining\", \"meaning\": \"ăn uống tại sân hiên\"}]', '[{\"word\": \"terrain\", \"note_vi\": \"địa hình\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/terrace-cori-2d5f4f20.mp3\", \"/storage/v1/object/public/pronunciation/v2/terrace-aru0-2d5f4f20.mp3\", \"/storage/v1/object/public/pronunciation/v2/terrace-aru5-2d5f4f20.mp3\", \"/storage/v1/object/public/pronunciation/v2/terrace-aru6-2d5f4f20.mp3\", \"/storage/v1/object/public/pronunciation/v2/terrace-aru10-2d5f4f20.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/terrace-aru9-2d5f4f20.mp3\", \"/storage/v1/object/public/pronunciation/v2/terrace-aru3-2d5f4f20.mp3\", \"/storage/v1/object/public/pronunciation/v2/terrace-aru7-2d5f4f20.mp3\", \"/storage/v1/object/public/pronunciation/v2/terrace-aru8-2d5f4f20.mp3\", \"/storage/v1/object/public/pronunciation/v2/terrace-aru2-2d5f4f20.mp3\"]}, \"us\