('e5028b67-d554-5b8f-bb69-246789366d0d', '4daa5e92-69f0-5c9b-a310-9387e8bc4326', 'fc7b95cc-1eb9-5ef4-9632-2ca30d8d27a5', '72530315-221e-55db-8135-bec87cb126a9', 'priority', 'UK: /praɪˈɒrəti/ | US: /praɪˈɔrəti/', 'B1', 'noun', 'sự ưu tiên', 'a thing that is regarded as more important than others and given chief concern', 'Customer satisfaction is our top priority.', 'Sự hài lòng của khách hàng là ưu tiên hàng đầu của chúng tôi.', '{\"en\": \"Improving customer service quality is our highest priority this year.\", \"vi\": \"Nâng cao chất lượng dịch vụ khách hàng là ưu tiên cao nhất của chúng tôi trong năm nay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/priority-ljspeech-3345867e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/priority-cori-3345867e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/priority-5885231a.webp', '[\"precedence\", \"preference\", \"urgency\"]', NULL, '[{\"phrase\": \"top priority\", \"meaning\": \"ưu tiên hàng đầu\"}, {\"phrase\": \"take priority over\", \"meaning\": \"được ưu tiên hơn\"}, {\"phrase\": \"set priorities\", \"meaning\": \"xác định các việc ưu tiên\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"prioritize\"}, {\"pos\": \"noun\", \"word\": \"prioritization\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/priority-cori-3345867e.mp3\", \"/storage/v1/object/public/pronunciation/v2/priority-aru0-3345867e.mp3\", \"/storage/v1/object/public/pronunciation/v2/priority-aru5-3345867e.mp3\", \"/storage/v1/object/public/pronunciation/v2/priority-aru6-3345867e.mp3\", \"/storage/v1/object/public/pronunciation/v2/priority-aru10-3345867e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/priority-aru9-3345867e.mp3\", \"/storage/v1/object/public/pronunciation/v2/priority-aru3-3345867e.mp3\", \"/storage/v1/object/public/pronunciation/v2/priority-aru7-3345867e.mp3\", \"/storage/v1/object/public/pronunciation/v2/priority-aru8-3345867e.mp3\", \"/storage/v1/object/p