('11097423-b421-5b63-84e0-ae8b6b0d22e3', '6a1d39c9-c971-58f9-8a58-d75deeb5a60f', '544bb5bb-f1ba-58ac-b10a-bea7871f3ad2', 'dc3118ff-6fbd-5a76-b2d8-fb019f59cac3', 'courier', 'UK: /ˈkʊriə/ | US: /ˈkʊriər/', 'B2', 'noun', 'người đưa thư, chuyển phát nhanh', 'a person or company employed to transport urgent messages, packages, or important mail', 'Please send the documents by courier service.', 'Vui lòng gửi tài liệu bằng dịch vụ chuyển phát nhanh.', '{\"en\": \"The signed contract was delivered to our legal office by express courier.\", \"vi\": \"Hợp đồng đã ký được gửi đến văn phòng luật của chúng tôi bằng dịch vụ chuyển phát nhanh.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/courier-ljspeech-023daeb6.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/courier-cori-023daeb6.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/courier-d3e13e61.webp', '[\"messenger\", \"carrier\", \"dispatcher\", \"runner\"]', NULL, '[{\"phrase\": \"express courier\", \"meaning\": \"chuyển phát nhanh\"}, {\"phrase\": \"courier service\", \"meaning\": \"dịch vụ chuyển phát\"}]', '[{\"word\": \"carrier\", \"note_vi\": \"hãng vận tải, công ty viễn thông\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/courier-cori-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru0-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru5-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru6-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru10-023daeb6.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/courier-aru9-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru3-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru7-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru8-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru2-023daeb6.mp3\"]}, \"us\": {\"nu\": [\"/