INSERT INTO system_vocabulary_words (id, set_id, topic_id, part_id, word, ipa, cefr, part_of_speech, meaning_vi, definition_en, example_en, example_vi, example_toeic, audio_us, audio_uk, image_url, synonyms, antonyms, phrases, confusables, word_family, audio_voices, note_vi, toeic_topic, difficulty_level, order_index) VALUES
('88c81e3d-ff3c-5fac-8f80-02a6e9f69e88', '6a1d39c9-c971-58f9-8a58-d75deeb5a60f', '6fcb6b2b-4e65-59d9-a8d5-ff4c6264d8f2', '50473f88-20d1-5564-8bdb-eec32e3f5746', 'faulty', 'UK: /ˈfɔːlti/ | US: /ˈfɔːlti/', 'B2', 'adjective', 'có lỗi, hỏng hóc', 'Working incorrectly or having a flaw or defect that impairs function.', 'The customer returned the faulty product for a refund.', 'Khách hàng đã trả lại sản phẩm bị lỗi để được hoàn tiền.', '{\"en\": \"Customers who received faulty electronics are entitled to a full refund within thirty days.\", \"vi\": \"Những khách hàng nhận được thiết bị điện tử bị lỗi có quyền được hoàn tiền đầy đủ trong vòng 30 ngày.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/faulty-ljspeech-a100643a.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/faulty-cori-a100643a.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/faulty-a8b64214.webp', '[\"defective\", \"flawed\", \"malfunctioning\"]', '[\"flawless\", \"perfect\", \"functional\"]', '[{\"phrase\": \"faulty equipment\", \"meaning\": \"thiết bị bị lỗi/hỏng\"}, {\"phrase\": \"faulty wiring\", \"meaning\": \"hệ thống dây điện bị lỗi\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"fault\"}, {\"pos\": \"adverb\", \"word\": \"faultily\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/faulty-cori-a100643a.mp3\", \"/storage/v1/object/public/pronunciation/v2/faulty-aru0-a100643a.mp3\", \"/storage/v1/object/public/pronunciation/v2/faulty-aru5-a100643a.mp3\", \"/storage/v1/object/public/pronunciation/v2/faulty-aru6-a100643a.mp3\", \"/storage/v1/object/public/pronunciation/v2/faulty-aru10-a100643a.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/faulty-aru9-a100643a.mp3\", \"/storage/v1/object/public/pronunciation/v2/faulty-aru3-a100643a.mp3\", \"/storage/v1/object/public/pronunciation/v2/faulty-aru7-a100643a.mp3\", \"/storage/v1/object/public/pronunciation/v2/faulty-aru8-a100643a.mp3\", \"/storage/v1/object/public/pronunciation/