('a4fd2400-ea35-5b37-8c22-10a5e4ac71bb', '6a1d39c9-c971-58f9-8a58-d75deeb5a60f', '74e8d70e-07fd-54af-a2e6-fde505c7abfd', '40810875-f2f8-579a-8a7c-8a8c7abb4012', 'eyeglass', 'UK: /ˈaɪˌɡlɑːs.ɪz/ | US: /ˈaɪˌɡlæs.ɪz/', 'B1', 'noun', 'kính mắt', 'a single lens framed in metal or plastic to correct vision defects.', 'She wears eyeglasses for reading fine print.', 'Cô ấy đeo kính để đọc chữ in nhỏ.', '{\"en\": \"The technician is wearing protective eyeglasses while operating the laboratory equipment.\", \"vi\": \"Kỹ thuật viên đang đeo kính mắt bảo hộ trong khi vận hành thiết bị phòng thí nghiệm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/eyeglass-ljspeech-52e72911.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/eyeglass-cori-52e72911.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/eyeglass-3233717b.webp', '[\"spectacles\", \"glasses\", \"eyewear\"]', NULL, '[{\"phrase\": \"wear eyeglasses\", \"meaning\": \"đeo kính mắt\"}, {\"phrase\": \"pair of eyeglasses\", \"meaning\": \"cặp kính mắt\"}, {\"phrase\": \"protective eyeglasses\", \"meaning\": \"kính mắt bảo hộ\"}]', '[{\"word\": \"sunglasses\", \"note_vi\": \"sunglasses là kính râm chống nắng, khác với eyeglasses là kính thuốc/kính đeo mắt thông thường\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/eyeglass-cori-52e72911.mp3\", \"/storage/v1/object/public/pronunciation/v2/eyeglass-aru0-52e72911.mp3\", \"/storage/v1/object/public/pronunciation/v2/eyeglass-aru5-52e72911.mp3\", \"/storage/v1/object/public/pronunciation/v2/eyeglass-aru6-52e72911.mp3\", \"/storage/v1/object/public/pronunciation/v2/eyeglass-aru10-52e72911.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/eyeglass-aru9-52e72911.mp3\", \"/storage/v1/object/public/pronunciation/v2/eyeglass-aru3-52e72911.mp3\", \"/storage/v1/object/public/pronunciation/v2/eyeglass-aru7-52e72911.mp3\", \"/storage/v1/object/public/pronunciation/v2/eyeglass-aru8-52e72911.mp3\", \"/storag