('efb321ad-5eda-5886-ad39-036e0bc3fb78', '6a1d39c9-c971-58f9-8a58-d75deeb5a60f', '826bac8a-8882-5821-859f-23924614b7eb', '8a4ea394-7479-5a0b-acf7-3766e6c68da0', 'typhoon', '/taɪˈfuːn/', 'B1', 'noun', 'cơn bão lớn có gió mạnh và mưa lớn, thường ở khu vực Tây Thái Bình Dương', 'a violent tropical storm with very strong winds in the western Pacific Ocean.', 'The island braced for the arrival of a powerful typhoon.', 'Hòn đảo chuẩn bị đối phó với sự đổ bộ của một cơn bão mạnh.', '{\"en\": \"The flight was delayed because a powerful typhoon was approaching the international airport.\", \"vi\": \"Chuyến bay đã bị hoãn vì một cơn bão nhiệt đới mạnh đang tiến gần đến sân bay quốc tế.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/typhoon-ljspeech-52c4c1e7.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/typhoon-cori-52c4c1e7.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/typhoon-fb3759de.webp', '[\"hurricane\", \"cyclone\", \"tropical storm\"]', NULL, '[{\"phrase\": \"powerful typhoon\", \"meaning\": \"cơn bão nhiệt đới mạnh\"}, {\"phrase\": \"typhoon warning\", \"meaning\": \"cảnh báo bão nhiệt đới\"}]', '[{\"word\": \"monsoon\", \"note_vi\": \"monsoon là gió mùa, mang mưa lớn nhưng ít phá hoại hơn\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/typhoon-cori-52c4c1e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/typhoon-aru0-52c4c1e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/typhoon-aru5-52c4c1e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/typhoon-aru6-52c4c1e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/typhoon-aru10-52c4c1e7.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/typhoon-aru9-52c4c1e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/typhoon-aru3-52c4c1e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/typhoon-aru7-52c4c1e7.mp3\", \"/storage/v1/object/public/pronunciation/v2/typhoon-aru8-52c4c1e7.mp3\", \"/storage/v1/object/public