('893217f8-7165-5864-8eec-1c2a3e4e22c6', '6a1d39c9-c971-58f9-8a58-d75deeb5a60f', '934cec82-8c10-5eb7-9e97-f02d06303e29', '44d927c4-e99d-5654-9d14-4c1c568008e4', 'essential', 'UK: /ɪˈsenʃəl/ | US: /ɪˈsenʃəl/', 'B1', 'adjective', 'thiết yếu, cần thiết', 'Absolutely necessary or extremely important for a particular task or outcome.', 'Reliable transportation is essential for this role.', 'Phương tiện đi lại đáng tin cậy là thiết yếu cho vai trò này.', '{\"en\": \"Good communication skills are essential for effective teamwork.\", \"vi\": \"Kỹ năng giao tiếp tốt là rất cần thiết cho việc làm việc nhóm hiệu quả.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/essential-ljspeech-16e73bca.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/essential-cori-16e73bca.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/essential-12eae2ff.webp', '[\"crucial\", \"vital\", \"necessary\", \"indispensable\"]', '[\"optional\", \"unnecessary\"]', '[{\"phrase\": \"essential for/to\", \"meaning\": \"thiết yếu cho\"}, {\"phrase\": \"play an essential role\", \"meaning\": \"đóng vai trò thiết yếu\"}]', NULL, '[{\"pos\": \"adverb\", \"word\": \"essentially\"}, {\"pos\": \"noun\", \"word\": \"essence\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/essential-cori-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru0-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru5-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru6-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru10-16e73bca.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/essential-aru9-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru3-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru7-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru8-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation