('235620c6-2ad5-561e-ba56-988b59be3405', '6a1d39c9-c971-58f9-8a58-d75deeb5a60f', '934cec82-8c10-5eb7-9e97-f02d06303e29', '44d927c4-e99d-5654-9d14-4c1c568008e4', 'address', 'UK: /əˈdres/ | US: /əˈdres/', 'B1', 'verb', 'diễn thuyết, nói chuyện trước công chúng', 'to speak formal words to a group of people assembled together', 'The CEO will address the employees at the annual meeting.', 'CEO sẽ phát biểu trước nhân viên tại cuộc họp thường niên.', '{\"en\": \"The keynote speaker will address the audience at the start of tomorrow\'s session.\", \"vi\": \"Diễn giả chính sẽ phát biểu trước khán giả vào đầu phiên họp ngày mai.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/address-ljspeech-c6621802.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/address-cori-c6621802.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/address-ac7693c9.webp', '[\"speak to\", \"lecture\", \"talk to\", \"greet\"]', '[\"ignore\"]', '[{\"phrase\": \"address an audience\", \"meaning\": \"diễn thuyết trước khán giả\"}, {\"phrase\": \"address a conference\", \"meaning\": \"phát biểu tại một hội nghị\"}]', '[{\"word\": \"redress\", \"note_vi\": \"đền bù, uốn nắn, sửa sai\"}]', '[{\"pos\": \"noun\", \"word\": \"address\"}, {\"pos\": \"noun\", \"word\": \"addressee\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/address-cori-c6621802.mp3\", \"/storage/v1/object/public/pronunciation/v2/address-aru0-c6621802.mp3\", \"/storage/v1/object/public/pronunciation/v2/address-aru5-c6621802.mp3\", \"/storage/v1/object/public/pronunciation/v2/address-aru6-c6621802.mp3\", \"/storage/v1/object/public/pronunciation/v2/address-aru10-c6621802.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/address-aru9-c6621802.mp3\", \"/storage/v1/object/public/pronunciation/v2/address-aru3-c6621802.mp3\", \"/storage/v1/object/public/pronunciation/v2/address-aru7-c6621802.mp3\", \"/storage/v1/object/public/pronunciation/v2/address-aru8-c6621802.mp3\