('64713341-87ff-5465-84e9-145d231961eb', '6a1d39c9-c971-58f9-8a58-d75deeb5a60f', 'f1404bc4-8ff4-5146-a87c-c92c40fa6199', 'e2e1e6e3-d9f8-58a2-b2de-b648ba90dcc3', 'order', '/ˈɔːdə(r)/', 'A1', 'noun', 'yêu cầu mua hàng hóa hoặc dịch vụ.', 'a request for a company to supply goods or services to a customer.', 'We received a large order for new books this morning.', 'Sáng nay chúng tôi đã nhận được một đơn hàng lớn sách mới.', '{\"en\": \"Please confirm your order number before we process the shipment from our warehouse.\", \"vi\": \"Vui lòng xác nhận mã đơn hàng của bạn trước khi chúng tôi xử lý việc vận chuyển từ kho.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/order-ljspeech-cce55e43.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/order-cori-cce55e43.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/order-b2fea733.webp', '[\"request\", \"purchase\"]', NULL, '[{\"phrase\": \"place an order\", \"meaning\": \"đặt hàng\"}, {\"phrase\": \"process an order\", \"meaning\": \"xử lý đơn hàng\"}]', NULL, '[{\"pos\": \"adjective\", \"word\": \"orderly\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/order-cori-cce55e43.mp3\", \"/storage/v1/object/public/pronunciation/v2/order-aru0-cce55e43.mp3\", \"/storage/v1/object/public/pronunciation/v2/order-aru5-cce55e43.mp3\", \"/storage/v1/object/public/pronunciation/v2/order-aru6-cce55e43.mp3\", \"/storage/v1/object/public/pronunciation/v2/order-aru10-cce55e43.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/order-aru9-cce55e43.mp3\", \"/storage/v1/object/public/pronunciation/v2/order-aru3-cce55e43.mp3\", \"/storage/v1/object/public/pronunciation/v2/order-aru7-cce55e43.mp3\", \"/storage/v1/object/public/pronunciation/v2/order-aru8-cce55e43.mp3\", \"/storage/v1/object/public/pronunciation/v2/order-aru2-cce55e43.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/order-ljspeech-cce55e43.mp3\", \"/storage/v1/object/public/pronunciati