('42087724-e942-5cf8-b69d-2e7f7bfcc3c4', '6a1d39c9-c971-58f9-8a58-d75deeb5a60f', 'f86af2d7-ee0f-569a-a8cd-d038c752fdec', 'cf36cb28-caf4-5fea-8b18-6c513c6097ca', 'businessperson', '/ˈbɪz.nɪsˌpɜː.sən/', 'A2', 'noun', 'người làm kinh doanh, điều hành một doanh nghiệp.', 'a person who works in commercial, financial, or corporate management.', 'She is a successful businessperson who owns several restaurants.', 'Cô ấy là một doanh nhân thành đạt, sở hữu nhiều nhà hàng.', '{\"en\": \"The successful businessperson delivered an inspiring speech at the annual international summit.\", \"vi\": \"Doanh nhân thành công đã trình bày một bài phát biểu đầy cảm hứng tại thượng đỉnh quốc tế hàng năm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/businessperson-ljspeech-a8e4772d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/businessperson-cori-a8e4772d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/businessperson-22b90891.webp', '[\"entrepreneur\", \"executive\"]', NULL, '[{\"phrase\": \"prominent businessperson\", \"meaning\": \"doanh nhân lỗi lạc\"}, {\"phrase\": \"shrewd businessperson\", \"meaning\": \"doanh nhân sắc sảo\"}]', '[{\"word\": \"businessman\", \"note_vi\": \"Businessperson dùng trung tính giới tính, bao gồm cả nam và nữ.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/businessperson-cori-a8e4772d.mp3\", \"/storage/v1/object/public/pronunciation/v2/businessperson-aru0-a8e4772d.mp3\", \"/storage/v1/object/public/pronunciation/v2/businessperson-aru5-a8e4772d.mp3\", \"/storage/v1/object/public/pronunciation/v2/businessperson-aru6-a8e4772d.mp3\", \"/storage/v1/object/public/pronunciation/v2/businessperson-aru10-a8e4772d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/businessperson-aru9-a8e4772d.mp3\", \"/storage/v1/object/public/pronunciation/v2/businessperson-aru3-a8e4772d.mp3\", \"/storage/v1/object/public/pronunciation/v2/businessperson-aru7-a8e4772d.mp3\", \"/storage/v1/