('db9dbde4-cbe6-5671-90d0-0d18abcd555e', '6a1d39c9-c971-58f9-8a58-d75deeb5a60f', 'f86af2d7-ee0f-569a-a8cd-d038c752fdec', 'cf36cb28-caf4-5fea-8b18-6c513c6097ca', 'audit', 'UK: /ˈɔːdɪt/ | US: /ˈɔːdɪt/', 'B2', 'verb', 'kiểm toán', 'to examine and inspect financial accounts or records officially to ensure accuracy and compliance.', 'The company decided to audit their financial records.', 'Công ty quyết định kiểm toán hồ sơ tài chính của họ.', '{\"en\": \"An accounting firm was hired to audit the company\'s financial records for accuracy.\", \"vi\": \"Một công ty kế toán đã được thuê để kiểm toán các hồ sơ tài chính của công ty nhằm đảm bảo tính chính xác.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/audit-ljspeech-7876153a.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/audit-cori-7876153a.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/audit-6834754d.webp', '[\"inspect\", \"examine\", \"scrutinize\", \"check\"]', NULL, '[{\"phrase\": \"audit financial records\", \"meaning\": \"kiểm toán hồ sơ tài chính\"}, {\"phrase\": \"audit the accounts\", \"meaning\": \"kiểm toán các tài khoản sổ sách\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"audit\"}, {\"pos\": \"noun\", \"word\": \"auditor\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/audit-cori-7876153a.mp3\", \"/storage/v1/object/public/pronunciation/v2/audit-aru0-7876153a.mp3\", \"/storage/v1/object/public/pronunciation/v2/audit-aru5-7876153a.mp3\", \"/storage/v1/object/public/pronunciation/v2/audit-aru6-7876153a.mp3\", \"/storage/v1/object/public/pronunciation/v2/audit-aru10-7876153a.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/audit-aru9-7876153a.mp3\", \"/storage/v1/object/public/pronunciation/v2/audit-aru3-7876153a.mp3\", \"/storage/v1/object/public/pronunciation/v2/audit-aru7-7876153a.mp3\", \"/storage/v1/object/public/pronunciation/v2/audit-aru8-7876153a.mp3\", \"/storage/v1/object/public/pronunciation/v2/audit-aru2-78761