('3b3c6012-2371-558c-84c6-9f36f2723329', '6a1d39c9-c971-58f9-8a58-d75deeb5a60f', 'f86af2d7-ee0f-569a-a8cd-d038c752fdec', 'cf36cb28-caf4-5fea-8b18-6c513c6097ca', 'assurance', 'UK: /əˈʃʊərəns/ | US: /əˈʃʊrəns/', 'B2', 'noun', 'sự đảm bảo', 'a positive statement or promise intended to give confidence about something.', 'The company provided assurance of job security.', 'Công ty đưa ra sự đảm bảo về an ninh công việc.', '{\"en\": \"The manager gave her assurance that the delayed shipment would arrive by tomorrow morning.\", \"vi\": \"Quản lý đã đưa ra lời đảm bảo rằng lô hàng bị chậm trễ sẽ đến trước sáng mai.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/assurance-ljspeech-f3753f1b.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/assurance-cori-f3753f1b.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/assurance-d34064da.webp', '[\"guarantee\", \"pledge\", \"promise\", \"certainty\"]', '[\"uncertainty\", \"doubt\"]', '[{\"phrase\": \"quality assurance\", \"meaning\": \"đảm bảo chất lượng\"}, {\"phrase\": \"give assurance\", \"meaning\": \"đưa ra sự đảm bảo\"}]', '[{\"word\": \"insurance\", \"note_vi\": \"Insurance là hợp đồng/dịch vụ bảo hiểm tài chính, còn assurance là lời cam đoan hoặc sự đảm bảo.\"}]', '[{\"pos\": \"verb\", \"word\": \"assure\"}, {\"pos\": \"adjective\", \"word\": \"assured\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/assurance-cori-f3753f1b.mp3\", \"/storage/v1/object/public/pronunciation/v2/assurance-aru0-f3753f1b.mp3\", \"/storage/v1/object/public/pronunciation/v2/assurance-aru5-f3753f1b.mp3\", \"/storage/v1/object/public/pronunciation/v2/assurance-aru6-f3753f1b.mp3\", \"/storage/v1/object/public/pronunciation/v2/assurance-aru10-f3753f1b.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/assurance-aru9-f3753f1b.mp3\", \"/storage/v1/object/public/pronunciation/v2/assurance-aru3-f3753f1b.mp3\", \"/storage/v1/object/public/pronunciation/v2/assurance-aru7-f3753f1b